/** Every zone name, sorted, with its POSIX string: [[name, posix], ...]. */
function tzZones() {
  return TZ_ZONES.split('|').map(z => { const [n, i] = z.split('='); return [n, TZ_RULES[+i]]; });
}

/** The POSIX string for a zone name, or '' for a name not in the table. */
function tzPosix(zone) {
  const z = tzZones().find(([n]) => n === zone);
  return z ? z[1] : '';
}

/** The zone names whose string is `posix` (several zones share one). */
function tzNamesFor(posix) { return tzZones().filter(([, p]) => p === posix).map(([n]) => n); }

// ---- store.js ----
// The connection to the device and everything it has told us. One EventSource on /events: ESPHome's web server
// sends a "ping" with the device's title and uptime, then every entity of the build with full detail (name,
// limits, options, ...), then a "state" event whenever one changes, "log" lines, and a "ping" every 10 seconds.
// The app reads the device only through here, and changes it only through api.js.

const LOG_MAX = 300;
const STALE_MS = 25000;  // no ping for this long: the connection is dead even if the browser has not noticed
const HIDDEN_RELEASE_MS = 30000;  // a page hidden this long gives its connection back (see start())

const store = {
  entities: new Map(),  // "domain/Name" -> the latest JSON the device sent for it (full detail kept)
  title: '',
  status: 'connecting',  // connecting | online | offline | paused (page hidden, connection given back)
  everOnline: false,
  lastNewEntity: 0,      // Date.now() when an entity was last seen for the first time
  logLines: [],          // {at, text}, newest last
  logCount: 0,           // lines received in total (so a view can tell which ones are new)
  uptimeS: null,
  uptimeAt: 0,
  _subs: new Set(),
  _watchers: new Set(),
  _changed: new Set(),
  _timer: 0,
  _es: null,
  _retry: 0,
  _lastMessage: 0,

  get(id) { return this.entities.get(id); },
  has(id) { return this.entities.has(id); },
  /** The value as text (text sensors, selects, texts), '' if unknown. */
  text(id) {
    const e = this.entities.get(id);
    return e ? String(e.value ?? e.state ?? '') : '';
  },
  /** The value as a number (sensors, numbers), NaN if unknown. */
  num(id) {
    const e = this.entities.get(id);
    if (!e || e.value === null || e.value === undefined) return NaN;
    return typeof e.value === 'number' ? e.value : parseFloat(e.value);
  },
  /** Binary sensors and switches: true, false, or undefined if not in this build. */
  bool(id) {
    const e = this.entities.get(id);
    return e ? e.value === true : undefined;
  },
  /** Seconds since the device booted, counted on from its last ping. */
  uptime() {
    return this.uptimeS === null ? null : this.uptimeS + (Date.now() - this.uptimeAt) / 1000;
  },

  /** fn(changed: Set of ids, plus "*status", "*ping", "*log") after each burst of updates. Returns unsubscribe. */
  subscribe(fn) {
    this._subs.add(fn);
    return () => this._subs.delete(fn);
  },
  /** fn(id) at once for every update (for code waiting on one entity). Returns unwatch. */
  watch(fn) {
    this._watchers.add(fn);
    return () => this._watchers.delete(fn);
  },

  _mark(id) {
    this._changed.add(id);
    for (const w of [...this._watchers]) w(id);
    if (!this._timer) this._timer = setTimeout(() => this._flush(), 40);
  },
  _flush() {
    this._timer = 0;
    const changed = this._changed;
    this._changed = new Set();
    for (const fn of [...this._subs]) fn(changed);
  },
  _setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    if (status === 'online') this.everOnline = true;
    this._mark('*status');
  },

  connect() {
    if (this._es) this._es.close();
    const es = new EventSource('/events');
    this._es = es;
    this._lastMessage = Date.now();
    const alive = () => { this._lastMessage = Date.now(); this._retry = 0; this._setStatus('online'); };
    es.onopen = alive;
    es.onerror = () => {
      if (this._es !== es) return;
      // Reconnect ourselves: ESPHome asks browsers to wait 30 s, too long for someone looking at the page.
      es.close();
      this._es = null;
      this._setStatus('offline');
      setTimeout(() => this.connect(), Math.min(10000, 1000 * 2 ** this._retry++));
    };
    es.addEventListener('ping', ev => {
      alive();
      try {
        const d = JSON.parse(ev.data);
        if (typeof d.title === 'string') this.title = d.title;
        if (typeof d.uptime === 'number') {
          // Uptime going backwards means the feeder restarted (a power cut, or an update).
          if (this.uptimeS !== null && d.uptime + 5 < this.uptime()) this._mark('*restart');
          this.uptimeS = d.uptime;
          this.uptimeAt = Date.now();
        }
      } catch (err) { /* a ping we cannot read changes nothing */ }
      this._mark('*ping');
    });
    es.addEventListener('state', ev => {
      alive();
      let d;
      try { d = JSON.parse(ev.data); } catch (err) { return; }
      // ESPHome 2026.x ids are "domain/Name"; build one from the detail if an older format ever arrives.
      let id = d.id;
      if (typeof id !== 'string' || !id.includes('/')) id = d.domain && d.name ? `${d.domain}/${d.name}` : null;
      if (!id) return;
      const prev = this.entities.get(id);
      if (prev) Object.assign(prev, d);
      else {
        this.entities.set(id, d);
        this.lastNewEntity = Date.now();
      }
      this._mark(id);
    });
    es.addEventListener('log', ev => {
      alive();
      this.logLines.push({ at: Date.now(), text: ev.data });
      this.logCount++;
      if (this.logLines.length > LOG_MAX) this.logLines.shift();
      this._mark('*log');
    });
  },

  start() {
    this.connect();
    setInterval(() => {
      if (this._es && this.status === 'online' && Date.now() - this._lastMessage > STALE_MS) {
        this._es.onerror();  // treat silence as a dropped connection
      }
    }, 5000);
    // The feeder's web server has only a few sockets, and drops the least recently used connection when they run
    // out (measured: about four open pages at once). So a page hidden for a while (a background tab, a phone in a
    // pocket) lets go of its connection, and takes a new one, with everything current, as soon as it is shown.
    let hiddenTimer = 0;
    document.addEventListener('visibilitychange', () => {
      clearTimeout(hiddenTimer);
      if (document.hidden) {
        hiddenTimer = setTimeout(() => {
          if (!this._es) return;
          this._es.close();
          this._es = null;
          this.status = 'paused';
          this._mark('*status');
        }, HIDDEN_RELEASE_MS);
      } else if (!this._es) {
        this._retry = 0;
        this.connect();
      }
    });
  },
};

// ---- auth.js ----
// The settings password (DESIGN.md section 10.1). The page is plain HTTP, where browsers offer no crypto.subtle, so
// SHA-256, HMAC and PBKDF2 are written out here (small, and tested against the device's vectors in
// tests/test_web.mjs). The password never leaves this page: it becomes a key (PBKDF2 with the device's salt), kept in
// memory only, and each protected change carries HMAC(key, one-time challenge || what is changed).

const SHA256_K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98,
  0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8,
  0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
  0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
  0xc67178f2]);
const SHA256_IV = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];

/** One 64-byte block into state h (8 words), in place. */
function sha256Block(h, block, w) {
  for (let i = 0; i < 16; i++)
    w[i] = (block[4 * i] << 24) | (block[4 * i + 1] << 16) | (block[4 * i + 2] << 8) | block[4 * i + 3];
  for (let i = 16; i < 64; i++) {
    const a = w[i - 15], b = w[i - 2];
    const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
    const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
    w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
  }
  let [a, b, c, d, e, f, g, k] = h;
  for (let i = 0; i < 64; i++) {
    const t1 = (k + (((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7))) +
                ((e & f) ^ (~e & g)) + SHA256_K[i] + w[i]) | 0;
    const t2 = ((((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10))) +
                ((a & b) ^ (a & c) ^ (b & c))) | 0;
    k = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
  }
  h[0] = (h[0] + a) | 0; h[1] = (h[1] + b) | 0; h[2] = (h[2] + c) | 0; h[3] = (h[3] + d) | 0;
  h[4] = (h[4] + e) | 0; h[5] = (h[5] + f) | 0; h[6] = (h[6] + g) | 0; h[7] = (h[7] + k) | 0;
}

/** SHA-256 of bytes, continuing from state `start` after `done` bytes (for HMAC's precomputed pads). */
function sha256From(start, done, bytes) {
  const h = start.slice(), w = new Int32Array(64);
  const total = done + bytes.length;
  const padded = new Uint8Array(((bytes.length + 9 + 63) >> 6) << 6);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const bits = total * 8;
  for (let i = 0; i < 4; i++) padded[padded.length - 1 - i] = (bits / 2 ** (8 * i)) & 0xff;
  for (let i = 0; i < padded.length; i += 64) sha256Block(h, padded.subarray(i, i + 64), w);
  const out = new Uint8Array(32);
  for (let i = 0; i < 8; i++) {
    out[4 * i] = h[i] >>> 24; out[4 * i + 1] = h[i] >>> 16; out[4 * i + 2] = h[i] >>> 8; out[4 * i + 3] = h[i];
  }
  return out;
}

function sha256(bytes) { return sha256From(SHA256_IV, 0, bytes); }

function concatBytes(...parts) {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) { out.set(p, at); at += p.length; }
  return out;
}

/** HMAC-SHA256 with the key's pads hashed once: returns (message bytes) => tag. */
function hmacSha256Keyed(key) {
  if (key.length > 64) key = sha256(key);
  const pad = (x) => {
    const block = new Uint8Array(64);
    for (let i = 0; i < 64; i++) block[i] = (key[i] || 0) ^ x;
    const h = SHA256_IV.slice();
    sha256Block(h, block, new Int32Array(64));
    return h;
  };
  const inner = pad(0x36), outer = pad(0x5c);
  return msg => sha256From(outer, 64, sha256From(inner, 64, msg));
}

function hmacSha256(key, msg) { return hmacSha256Keyed(key)(msg); }

/** PBKDF2-HMAC-SHA256, one 32-byte block (all the device needs). */
function pbkdf2Sha256(password, salt, iterations) {
  const mac = hmacSha256Keyed(password);
  let u = mac(concatBytes(salt, new Uint8Array([0, 0, 0, 1])));
  const out = u.slice();
  for (let i = 1; i < iterations; i++) {
    u = mac(u);
    for (let j = 0; j < 32; j++) out[j] ^= u[j];
  }
  return out;
}

const utf8 = s => new TextEncoder().encode(s);
const toHex = bytes => Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
function fromHex(hex) {
  const out = new Uint8Array(hex.length >> 1);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(2 * i, 2), 16);
  return out;
}

/** What a protected entity change is signed over: the path the device sees and the value written. */
function authMessage(path, value) { return `${path}\n${value === undefined || value === null ? '' : String(value)}`; }

/** The X-Feeder-Auth header: nonce then HMAC(key, nonce || message), in hex. */
function authHeader(key, nonce, message) { return toHex(nonce) + toHex(hmacSha256(key, concatBytes(nonce, utf8(message)))); }

/** A new key travels masked by the current one (none: unmasked), as FeederCore::password_unmask expects. */
function maskKey(newKey, currentKey, nonce) {
  if (!currentKey) return newKey.slice();
  const mask = hmacSha256(currentKey, concatBytes(nonce, utf8('new key')));
  return newKey.map((b, i) => b ^ mask[i]);
}

/** A secret text (a Wi-Fi or access-point password, up to 64 bytes) travels masked like a key, by two HMAC blocks, as
 *  FeederCore::password_unmask_text expects (none: unmasked). */
function maskText(text, currentKey, nonce) {
  const bytes = utf8(text);
  if (!currentKey) return bytes;
  const mask = concatBytes(hmacSha256(currentKey, concatBytes(nonce, utf8('new secret 1'))),
                           hmacSha256(currentKey, concatBytes(nonce, utf8('new secret 2'))));
  return bytes.map((b, i) => b ^ mask[i]);
}

/** A 32-byte key as base64, as ESPHome (api: encryption: key) and the BLE clients write it. */
function keyToBase64(bytes) { return btoa(String.fromCharCode(...bytes)); }
/** A key typed in: base64 of exactly 32 bytes, not all zero; null otherwise. */
function keyFromBase64(text) {
  let raw;
  try { raw = atob(String(text).trim()); } catch (e) { return null; }
  if (raw.length !== 32) return null;
  const bytes = Uint8Array.from(raw, ch => ch.charCodeAt(0));
  return bytes.some(b => b !== 0) ? bytes : null;
}

const auth = {
  available: false,   // the device has the settings guard (the web server package with it)
  set: false,         // a settings password is set
  key: null,          // the derived key once unlocked (memory only: a reload locks again)
  protectedIds: new Set(),
  // Where the API (Home Assistant) and BLE keys come from: none, build (the YAML's), device (saved on it) or off
  // (this build cannot have one). The device never sends a key.
  keys: { api: 'off', ble: 'off' },
  _listeners: [],

  onChange(fn) { this._listeners.push(fn); },
  _changed() { for (const fn of this._listeners) fn(); },

  /** Ask the device for a challenge (and its current state). */
  async challenge() {
    const r = await fetch(`${location.origin}/feeder/auth`, { cache: 'no-store' });
    if (!r.ok) throw new Error(`The feeder answered ${r.status}.`);
    const c = await r.json();
    this.available = true;
    this.set = c.scheme !== 0;
    if (!this.set) this.key = null;
    this.protectedIds = new Set(c.protected || []);
    this.keys = Object.assign({ api: 'off', ble: 'off' }, c.keys || {});
    c.nonceBytes = fromHex(c.nonce);
    c.saltBytes = fromHex(c.salt);
    return c;
  },
  async refresh() {
    try { await this.challenge(); } catch (e) { this.available = false; }
    this._changed();
  },
  isProtected(id) { return this.protectedIds.has(id); },
  locked() { return this.set && !this.key; },

  /** Headers for a request to `path` writing `value`: {} without a password; throws while locked. */
  async headersFor(path, value) {
    const c = await this.challenge();
    if (!this.set) return {};
    if (!this.key) throw new Error('Locked: unlock with the settings password (Configuration) first.');
    return { 'X-Feeder-Auth': authHeader(this.key, c.nonceBytes, authMessage(path, value)) };
  },

  /** Turn a refused answer into a message. */
  async refusal(r) {
    let wait = 0;
    try { wait = (await r.json()).wait || 0; } catch (e) { /* no body */ }
    if (r.status === 429) return new Error(`Too many tries: wait ${Math.ceil(wait / 1000)} s.`);
    if (r.status === 403) {
      this.key = null;
      this._changed();
      return new Error('The settings password was not accepted. Unlock again.');
    }
    return new Error(`The feeder answered ${r.status}.`);
  },

  async unlock(password) {
    const c = await this.challenge();
    if (!this.set) return;
    const key = pbkdf2Sha256(utf8(password), c.saltBytes, c.iterations);
    const path = '/feeder/auth/check';
    const r = await fetch(location.origin + path, { method: 'POST',
      headers: { 'X-Feeder-Auth': authHeader(key, c.nonceBytes, authMessage(path, '')) } });
    if (!r.ok) {
      const err = await this.refusal(r);
      throw r.status === 403 ? new Error('That is not the settings password.') : err;
    }
    this.key = key;
    this._changed();
  },

  lock() { this.key = null; this._changed(); },

  /** Save a 32-byte key ('api' or 'ble') on the device, masked like a new password key, or clear the API key with
   *  null. Signed with the settings password when one is set. The device never sends a key back. */
  async setKey(kind, bytes) {
    const c = await this.challenge();
    if (this.set && !this.key) throw new Error('Locked: unlock with the settings password first.');
    const path = `/feeder/keys/${kind}`;
    const keyHex = bytes ? toHex(maskKey(bytes, this.set ? this.key : null, c.nonceBytes)) : '';
    const headers = this.set ? { 'X-Feeder-Auth': authHeader(this.key, c.nonceBytes, authMessage(path, keyHex)) } : {};
    let r;
    try {
      r = await fetch(location.origin + path + (keyHex ? `?key=${keyHex}` : ''), { method: 'POST', headers });
    } catch (e) {
      throw new Error('The feeder could not be reached.');
    }
    if (r.status === 403 || r.status === 429) throw await this.refusal(r);
    if (r.status === 409) throw new Error('This build cannot change that key: it comes from the YAML.');
    if (!r.ok) throw new Error(`The feeder answered ${r.status}.`);
    await this.refresh();
  },

  /** The network settings (DESIGN.md section 9.3): the name in use, saved and the build's, where the access point's
   *  password comes from (build, device or off), whether Wi-Fi can be set, and whether a restart is due. Null when the
   *  device does not answer. */
  network: null,
  async loadNetwork() {
    try {
      const r = await fetch(`${location.origin}/feeder/network`, { cache: 'no-store' });
      this.network = r.ok ? await r.json() : null;
    } catch (e) {
      this.network = null;
    }
    this._changed();
    return this.network;
  },

  /** Save a network setting: ('name', {name}) ('' for the build's), ('ap', {password}) ('' for the build's) or
   *  ('wifi', {ssid, password}). Passwords travel masked by the settings password; all are signed with it. */
  async setNetwork(kind, values) {
    const c = await this.challenge();
    if (this.set && !this.key) throw new Error('Locked: unlock with the settings password first.');
    const path = `/feeder/network/${kind}`;
    const secret = text => (text ? toHex(maskText(text, this.set ? this.key : null, c.nonceBytes)) : '');
    let signed, query;
    if (kind === 'name') {
      signed = values.name;
      query = `name=${encodeURIComponent(values.name)}`;
    } else if (kind === 'ap') {
      signed = secret(values.password);
      query = `password=${signed}`;
    } else if (kind === 'forget') {  // 2.3.0: nothing to send but the signature
      signed = '';
      query = '';
    } else {
      // A scanned network comes as the hex the feeder sent (2.3.0), a typed one as text.
      const ssid = values.ssidHex || toHex(utf8(values.ssid)), password = secret(values.password);
      signed = ssid + password;
      query = `ssid=${ssid}&password=${password}`;
    }
    const headers = this.set ? { 'X-Feeder-Auth': authHeader(this.key, c.nonceBytes, authMessage(path, signed)) } : {};
    let r;
    try {
      r = await fetch(`${location.origin}${path}?${query}`, { method: 'POST', headers });
    } catch (e) {
      throw new Error('The feeder could not be reached.');
    }
    if (r.status === 403 || r.status === 429) throw await this.refusal(r);
    if (r.status === 409) throw new Error('This build cannot change that.');
    if (r.status === 400) throw new Error('The feeder did not accept that value.');
    if (!r.ok) throw new Error(`The feeder answered ${r.status}.`);
    if (kind !== 'wifi') await this.loadNetwork();
  },

  /** The setup wizard finished or skipped (true), or to be offered again (false). Signed when a password is set. */
  async setSetupDone(done) {
    const c = await this.challenge();
    if (this.set && !this.key) throw new Error('Locked: unlock with the settings password first.');
    const path = '/feeder/setup', value = done ? '1' : '0';
    const headers = this.set ? { 'X-Feeder-Auth': authHeader(this.key, c.nonceBytes, authMessage(path, value)) } : {};
    const r = await fetch(`${location.origin}${path}?done=${value}`, { method: 'POST', headers });
    if (r.status === 403 || r.status === 429) throw await this.refusal(r);
    if (!r.ok) throw new Error(`The feeder answered ${r.status}.`);
    await this.loadNetwork();
  },

  /** Upload a firmware image (DESIGN.md section 9.5), signed over its SHA-256 (hex), which the device checks again
   *  before it switches to it. XHR, not fetch, for the upload's progress. Resolves once the device has the image
   *  checked and restarts into it. */
  async uploadFirmware(bytes, shaHex, onProgress) {
    const c = await this.challenge();
    if (this.set && !this.key) throw new Error('Locked: unlock with the settings password first.');
    const path = '/feeder/firmware';
    const xhr = new XMLHttpRequest();
    xhr.open('POST', `${location.origin}${path}?sha256=${shaHex}`);
    xhr.setRequestHeader('Content-Type', 'application/octet-stream');
    if (this.set) xhr.setRequestHeader('X-Feeder-Auth', authHeader(this.key, c.nonceBytes, authMessage(path, shaHex)));
    xhr.upload.onprogress = e => { if (e.lengthComputable && onProgress) onProgress(e.loaded / e.total); };
    const status = await new Promise(resolve => {
      xhr.onload = () => resolve(xhr.status);
      xhr.onerror = () => resolve(0);
      xhr.send(bytes);
    });
    if (status === 200) return;
    if (status === 0) throw new Error('The upload was cut off; the feeder keeps its firmware. Try again.');
    if (status === 403 || status === 429) {
      throw await this.refusal({ status, json: async () => JSON.parse(xhr.responseText || '{}') });
    }
    let error = '';
    try { error = JSON.parse(xhr.responseText).error; } catch (e) { /* no body */ }
    throw new Error({
      sha256: 'The file changed on the way; nothing changed. Try again.',
      incomplete: 'The upload was cut off; nothing changed. Try again.',
      flash: 'The feeder refused the image (wrong board, or too big); nothing changed.',
      image: 'That is not an update image (a .factory.bin is for USB); nothing changed.',
    }[error] || `The feeder answered ${status}; nothing changed.`);
  },

  /** Set a new password (or change it: needs to be unlocked), or clear it with ''. */
  async setPassword(password) {
    const c = await this.challenge();
    if (this.set && !this.key) throw new Error('Unlock with the current password first.');
    const path = '/feeder/auth/password';
    let query = '', saltHex = '', keyHex = '', newKey = null;
    if (password) {
      const salt = crypto.getRandomValues(new Uint8Array(16));
      newKey = pbkdf2Sha256(utf8(password), salt, c.iterations);
      saltHex = toHex(salt);
      keyHex = toHex(maskKey(newKey, this.set ? this.key : null, c.nonceBytes));
      query = `?salt=${saltHex}&key=${keyHex}`;
    }
    const headers = this.set ? { 'X-Feeder-Auth': authHeader(this.key, c.nonceBytes, `${path}\n${saltHex}${keyHex}`) } : {};
    const r = await fetch(location.origin + path + query, { method: 'POST', headers });
    if (!r.ok) throw await this.refusal(r);
    this.key = newKey;
    this.set = !!password;
    this._changed();
  },
};

// ---- api.js ----
// Changes to the device: ESPHome's web server actions (POST /<domain>/<name>/<action>), one at a time, so the
// device's few HTTP sockets are never flooded and writes arrive in the order they were made. The device answers
// 200 as soon as it has queued an action; whether it took effect shows up as the entity's next state, which the
// firmware publishes within about a second (waitFor). Nothing here decides anything about feeding: the device's
// feed guard does, for every request. Which settings need the settings password is the device's list, too.

const api = {
  _queue: Promise.resolve(),

  /** Run an action on an entity, after every earlier one. Rejects if the device refuses or cannot be reached. */
  call(id, action, params) {
    const slash = id.indexOf('/');
    const domain = id.slice(0, slash), name = id.slice(slash + 1);
    const query = params ? Object.entries(params)
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&') : '';
    const url = `/${domain}/${encodeURIComponent(name)}/${action}${query ? '?' + query : ''}`;
    // From the origin, not relative: a page opened as http://user:pass@feeder/ would otherwise put the credentials
    // into every request URL, which browsers refuse. The browser still sends the cached credentials.
    // A protected setting (guard limits, calibration) carries the settings password's proof (auth.js), made just
    // before sending because each challenge is good for one request.
    const run = async () => {
      let headers = {};
      if (auth.isProtected(id)) {
        const value = params ? (params.value !== undefined ? params.value : params.option) : undefined;
        try {
          headers = await auth.headersFor(`/${domain}/${name}/${action}`, value);
        } catch (e) {
          throw e instanceof TypeError ? new Error('The feeder could not be reached.') : e;
        }
      }
      let r;
      try {
        r = await fetch(location.origin + url, { method: 'POST', headers });
      } catch (e) {
        throw new Error('The feeder could not be reached.');
      }
      if (r.status === 403 || r.status === 429) throw await auth.refusal(r);
      if (!r.ok) throw new Error(r.status === 404 ? 'This build does not have that control.' : `The feeder answered ${r.status}.`);
    };
    const done = this._queue.then(run, run);
    this._queue = done.catch(() => {});
    return done;
  },
  press(id) { return this.call(id, 'press'); },
  turn(id, on) { return this.call(id, on ? 'turn_on' : 'turn_off'); },
  setNumber(id, value) { return this.call(id, 'set', { value }); },
  setOption(id, option) { return this.call(id, 'set', { option }); },
  setText(id, value) { return this.call(id, 'set', { value }); },

  /** Resolve with the entity once pred(entity) holds (now or after an update); reject after `ms`. */
  waitFor(id, pred, ms = 4000) {
    return new Promise((resolve, reject) => {
      let timer = 0;
      const unwatch = store.watch(changed => {
        if (changed !== id) return;
        const e = store.get(id);
        if (e && pred(e)) finish(e);
      });
      const finish = e => { clearTimeout(timer); unwatch(); resolve(e); };
      const now = store.get(id);
      if (now && pred(now)) return finish(now);
      timer = setTimeout(() => { unwatch(); reject(new Error('The feeder did not confirm the change.')); }, ms);
    });
  },

  /** Resolve true once done() holds (now, or after one of `ids` changes), false after `ms` (never rejects).
   *  done() is checked first: the device's update can arrive before the request that caused it has returned. */
  waitForChange(ids, done, ms = 3500) {
    return new Promise(resolve => {
      if (done()) {
        resolve(true);
        return;
      }
      const timer = setTimeout(() => { unwatch(); resolve(false); }, ms);
      const unwatch = store.watch(id => {
        if (ids.includes(id) && done()) {
          clearTimeout(timer);
          unwatch();
          resolve(true);
        }
      });
    });
  },

  /** Turn a switch on or off and wait until the device reports it. */
  turnAndConfirm(id, on, ms = 4000) {
    return this.turn(id, on).then(() => this.waitFor(id, x => x.value === on, ms));
  },

  /** Set a number, select or text, then wait until the device reports the new value. */
  setAndConfirm(id, value, ms = 4000) {
    const e = store.get(id);
    if (!e) return Promise.reject(new Error('This build does not have that setting.'));
    let write, same;
    if (e.domain === 'number' || id.startsWith('number/')) {
      const step = parseFloat(e.step) || 1;
      write = this.setNumber(id, value);
      same = x => Math.abs(parseFloat(x.value) - parseFloat(value)) < step / 2;
    } else if (id.startsWith('select/')) {
      write = this.setOption(id, value);
      same = x => x.value === value;
    } else {
      write = this.setText(id, value);
      same = x => x.value === value;
    }
    return write.then(() => this.waitFor(id, same, ms));
  },
};

// ---- ui.js ----
// DOM helpers and the small widgets every page shares. No framework: pages build their DOM once with h() and
// update the parts that change.

/** Pages register here: PAGES.<tab id> = {mount(el, route), update(changed), unmount()}. */
const PAGES = {};

/** h('div', {class: 'x', onclick: fn}, child, 'text', [more]) -> an element. */
function h(tag, props, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(props || {})) {
    if (v === null || v === undefined || v === false) continue;
    if (k === 'class') el.className = v;
    else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2).toLowerCase(), v);
    else if (k === 'value') el.value = v;
    else if (k === 'checked') el.checked = v;
    else el.setAttribute(k, v === true ? '' : v);
  }
  append(el, children);
  return el;
}

/** Append children: nodes, text, or (nested) arrays of them; null, undefined and false are skipped. */
function append(el, ...children) {
  for (const c of children.flat(Infinity)) {
    if (c === null || c === undefined || c === false) continue;
    el.appendChild(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
  return el;
}

/** Set an element's text only when it changes (keeps the DOM quiet). */
function setText(el, text) {
  const t = text === null || text === undefined ? '' : String(text);
  if (el.textContent !== t) el.textContent = t;
}

// ---- icons: 24 x 24 outline paths, drawn for this app ----
const ICONS = {
  grid: 'M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z',
  calendar: 'M4 6h16v14H4zM4 10h16M8 3v5M16 3v5',
  sliders: 'M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1M15 4v4M9 10v4M17 16v4',
  tool: 'M14.5 4.5a4.5 4.5 0 0 0-5.6 5.6L3.5 15.5l5 5 5.4-5.4a4.5 4.5 0 0 0 5.6-5.6l-2.8 2.8-2.6-.4-.4-2.6z',
  bluetooth: 'M7 7l10 10-5 5V2l5 5L7 17',
  activity: 'M3 12h4l3-8 4 16 3-8h4',
  fish: 'M2.5 12c3-5 9.5-6.5 14 0-4.5 6.5-11 5-14 0zM16.5 12l5-3.5v7zM8 11h.01',
  alert: 'M12 3l10 18H2zM12 10v4M12 17.5h.01',
  wifiOff: 'M3 3l18 18M8.5 16.5a5 5 0 0 1 7 0M5 13a10 10 0 0 1 4.5-2.4M19 13a10 10 0 0 0-2.2-1.6M2 9.5a15 15 0 0 1 4-2.6M22 9.5A15 15 0 0 0 11 5.6M12 20h.01',
  clock: 'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18zM12 7v5l3 2',
  pause: 'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18zM10 9v6M14 9v6',
  bowl: 'M3 11h18a9 9 0 0 1-18 0zM9 7.5c0-1.2.8-2 1.8-2.4M14 7c0-1.2.8-2 1.8-2.4',
  tune: 'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18zM12 3v4M12 17v4M3 12h4M17 12h4M12 12l3.5-3.5',
  check: 'M5 12.5l4.5 4.5L19 7.5',
  x: 'M6 6l12 12M18 6L6 18',
  info: 'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18zM12 11v6M12 7.5h.01',
  search: 'M10.5 4a6.5 6.5 0 1 0 0 13 6.5 6.5 0 1 0 0-13zM15.5 15.5L20 20',
  copy: 'M9 9h11v11H9zM5 15V4h11',
  refresh: 'M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7',
};

function icon(name, size = 20) {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('width', size);
  svg.setAttribute('height', size);
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('class', 'icon');
  const path = document.createElementNS(ns, 'path');
  path.setAttribute('d', ICONS[name] || ICONS.info);
  svg.appendChild(path);
  return svg;
}

// ---- toasts ----
function toast(message, kind = 'info', ms = 4000) {
  const box = document.getElementById('toasts');
  if (!box) return;
  const el = h('div', { class: `toast toast-${kind}`, role: kind === 'error' ? 'alert' : 'status' },
               icon(kind === 'error' ? 'alert' : kind === 'ok' ? 'check' : 'info', 18), h('span', {}, message));
  box.appendChild(el);
  setTimeout(() => {
    el.classList.add('toast-out');
    setTimeout(() => el.remove(), 300);
  }, ms);
}

/** Toast an error from a rejected api call. */
function toastError(err) {
  toast(err && err.message ? err.message : String(err), 'error', 6000);
}

// ---- dialogs ----
/** Show a dialog whose form has buttons valued "ok" and "cancel"; resolve true for OK, false otherwise. Resolves on
 *  the submit itself (and on Escape): browsers may hold back a dialog's "close" event while the page is not being
 *  drawn (a hidden tab), so that event is only a fallback. validate() may return a message to keep it open. */
function runDialog(dlg, form, validate, error) {
  return new Promise(resolve => {
    let done = false;
    const finish = ok => {
      if (done) return;
      done = true;
      if (dlg.open) dlg.close(ok ? 'ok' : 'cancel');
      setTimeout(() => dlg.remove(), 0);
      resolve(ok);
    };
    form.addEventListener('submit', ev => {
      const ok = !!ev.submitter && ev.submitter.value === 'ok';
      const message = ok && validate ? validate() : '';
      ev.preventDefault();
      if (message) {
        setText(error, message);
        return;
      }
      finish(ok);
    });
    dlg.addEventListener('cancel', () => finish(false));
    dlg.addEventListener('close', () => finish(dlg.returnValue === 'ok'));
    document.body.appendChild(dlg);
    dlg.showModal();
  });
}

/** A modal question. body: text or nodes. Resolves true for OK, false for Cancel or Escape. */
function confirmDialog({ title, body, ok = 'OK', cancel = 'Cancel', danger = false }) {
  const form = h('form', { method: 'dialog' },
    h('h2', { id: 'dlg-title' }, title),
    h('div', { class: 'dialog-body' }, typeof body === 'string' ? h('p', {}, body) : body),
    h('div', { class: 'dialog-actions' },
      h('button', { value: 'cancel', class: 'btn' }, cancel),
      h('button', { value: 'ok', class: danger ? 'btn btn-danger' : 'btn btn-primary' }, ok)));
  return runDialog(h('dialog', { class: 'dialog', 'aria-labelledby': 'dlg-title' }, form), form);
}

/** A modal form. body: nodes with the inputs. validate() returns an error message to keep it open, or ''.
 *  Resolves true for OK (after validation), false for Cancel or Escape. */
function formDialog({ title, body, ok = 'Save', cancel = 'Cancel', validate = () => '' }) {
  const error = h('p', { class: 'dialog-error', role: 'alert' });
  const form = h('form', { method: 'dialog' },
    h('h2', { id: 'dlg-title' }, title),
    h('div', { class: 'dialog-body dialog-form' }, body),
    error,
    h('div', { class: 'dialog-actions' },
      h('button', { value: 'cancel', class: 'btn', formnovalidate: true }, cancel),
      h('button', { value: 'ok', class: 'btn btn-primary' }, ok)));
  // Enter in a field means OK (the browser would otherwise use the first button, Cancel).
  form.addEventListener('keydown', ev => {
    if (ev.key === 'Enter' && ev.target.tagName === 'INPUT') {
      ev.preventDefault();
      form.requestSubmit(form.querySelector('button[value="ok"]'));
    }
  });
  form.addEventListener('input', () => setText(error, ''));
  return runDialog(h('dialog', { class: 'dialog', 'aria-labelledby': 'dlg-title' }, form), form, validate, error);
}

// ---- weekday chips (Monday first; names from the browser's locale; masks as the firmware: bit 0 = Sunday) ----
const WEEK_ORDER = [1, 2, 3, 4, 5, 6, 0];
function weekdayName(day, style) {
  return new Date(Date.UTC(2023, 0, 1 + day)).toLocaleDateString(undefined, { weekday: style, timeZone: 'UTC' });
}

/** Seven day chips for a weekday mask. Editable chips toggle; read the result from .mask. */
function dayChips(mask, editable = false, label = 'Days') {
  // Read-only chips are hidden from screen readers; the page states the days in words next to them.
  const box = h('div', { class: editable ? 'chips chips-edit' : 'chips', role: editable ? 'group' : null,
                         'aria-label': editable ? label : null, 'aria-hidden': editable ? null : 'true' });
  box.mask = mask & 0x7f;
  for (const day of WEEK_ORDER) {
    const on = () => !!(box.mask & (1 << day));
    const chip = h(editable ? 'button' : 'span', {
      type: editable ? 'button' : null, class: 'chip', title: weekdayName(day, 'long'),
      'aria-label': editable ? weekdayName(day, 'long') : null,
      onclick: editable ? () => {
        box.mask ^= 1 << day;
        chip.classList.toggle('chip-on', on());
        chip.setAttribute('aria-pressed', on() ? 'true' : 'false');
        box.dispatchEvent(new Event('input', { bubbles: true }));
      } : null,
    }, weekdayName(day, 'narrow'));
    chip.classList.toggle('chip-on', on());
    if (editable) chip.setAttribute('aria-pressed', on() ? 'true' : 'false');
    box.appendChild(chip);
  }
  return box;
}

/** Days in words: "Every day", "Weekdays", "Mon, Wed, Fri", "No days". */
function daysWords(mask) {
  mask &= 0x7f;
  if (mask === 0x7f) return 'Every day';
  if (mask === 0) return 'No days';
  if (mask === 0x3e) return 'Weekdays';
  if (mask === 0x41) return 'Weekends';
  return WEEK_ORDER.filter(d => mask & (1 << d)).map(d => weekdayName(d, 'short')).join(', ');
}

/** A row of choices; .value is the chosen one. options: [[value, label], ...]. */
function segmented(options, value, label, onchange) {
  const box = h('div', { class: 'segmented', role: 'radiogroup', 'aria-label': label });
  box.value = value;
  const buttons = options.map(([v, text]) => h('button', { type: 'button', role: 'radio', class: 'seg',
    'aria-checked': v === value ? 'true' : 'false', onclick: () => {
      box.value = v;
      buttons.forEach((b, i) => b.setAttribute('aria-checked', options[i][0] === v ? 'true' : 'false'));
      if (onchange) onchange(v);
      box.dispatchEvent(new Event('input', { bubbles: true }));
    } }, text));
  append(box, buttons);
  return box;
}

/** A minus / value / plus stepper between lo and hi; .value is the number. */
function stepper(value, lo, hi, label) {
  const shown = h('span', { class: 'stepper-value', 'aria-live': 'polite' }, String(value));
  const box = h('div', { class: 'stepper', role: 'group', 'aria-label': label });
  box.value = value;
  const set = v => {
    box.value = Math.min(hi, Math.max(lo, v));
    setText(shown, String(box.value));
  };
  append(box, h('button', { type: 'button', class: 'btn btn-small', 'aria-label': `${label}: less`, onclick: () => set(box.value - 1) }, '\u2212'),
         shown, h('button', { type: 'button', class: 'btn btn-small', 'aria-label': `${label}: more`, onclick: () => set(box.value + 1) }, '+'));
  return box;
}

/** A labelled field for dialogs. */
function field(label, control, hint) {
  return h('div', { class: 'form-field' }, h('span', { class: 'form-label' }, label), control,
           hint ? h('span', { class: 'hint' }, hint) : null);
}

// ---- layout helpers ----
function card(title, ...children) {
  return h('section', { class: 'card' }, title ? h('h2', { class: 'card-title' }, title) : null, ...children);
}

/** A label / value row; returns {row, value} so the value can be updated. */
function row(label, value = '') {
  const v = h('span', { class: 'row-value' }, value);
  return { row: h('div', { class: 'row' }, h('span', { class: 'row-label' }, label), v), value: v };
}

/** A label row whose value is kept in step with an entity: fn(store) -> text. Returns an updater. */
function boundRow(parent, label, fn) {
  const r = row(label);
  parent.appendChild(r.row);
  return () => setText(r.value, fn());
}

// ---- controls for any entity (the All entities list; reused by settings pages) ----

/** A control for entity `id` that writes through api and reports the outcome; null for read-only entities. */
function entityControl(id) {
  const e = store.get(id);
  if (!e) return null;
  const domain = e.domain || id.slice(0, id.indexOf('/'));
  const label = e.name || id;
  if (domain === 'button') {
    return h('button', { class: 'btn btn-small', 'aria-label': `Press ${label}`, onclick: async () => {
      if (!await confirmDialog({ title: `Press "${label}"?`, body: 'This acts on the feeder straight away.', ok: 'Press' })) return;
      api.press(id).then(() => toast(`Pressed ${label}`, 'ok'), toastError);
    } }, 'Press');
  }
  if (domain === 'switch') {
    const btn = h('button', { class: 'btn btn-small', role: 'switch', 'aria-label': label, onclick: () => {
      const on = !store.bool(id);
      api.turn(id, on).then(() => api.waitFor(id, x => x.value === on)).catch(toastError);
    } });
    btn._update = () => {
      const on = store.bool(id);
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
      setText(btn, on ? 'On' : 'Off');
      btn.classList.toggle('btn-on', !!on);
    };
    btn._update();
    return btn;
  }
  if (domain === 'select') {
    const sel = h('select', { class: 'input', 'aria-label': label, onchange: () => {
      api.setAndConfirm(id, sel.value).catch(err => { toastError(err); sel._update(); });
    } }, (e.option || []).map(o => h('option', { value: o }, o)));
    sel._update = () => { if (document.activeElement !== sel) sel.value = store.text(id); };
    sel._update();
    return sel;
  }
  if (domain === 'number' || domain === 'text') {
    const isNum = domain === 'number';
    const input = h('input', isNum
      ? { class: 'input input-num', type: 'number', inputmode: 'decimal', min: e.min_value, max: e.max_value,
          step: e.step, 'aria-label': label }
      // A password text (mode 1) is never sent back: the box starts empty.
      : { class: 'input', type: e.mode === 1 ? 'password' : 'text', maxlength: e.max_length, 'aria-label': label });
    const err = h('span', { class: 'field-error', 'aria-live': 'polite' });
    const save = () => {
      setText(err, '');
      const v = input.value.trim();
      if (isNum) {
        const x = parseFloat(v), lo = parseFloat(e.min_value), hi = parseFloat(e.max_value);
        if (v === '' || isNaN(x)) return setText(err, 'Enter a number');
        if (x < lo || x > hi) return setText(err, `From ${e.min_value} to ${e.max_value}`);
      }
      api.setAndConfirm(id, isNum ? parseFloat(v) : v)
        .then(() => toast(`${label} saved`, 'ok'), x => { toastError(x); input._update(true); });
    };
    input.addEventListener('keydown', ev => { if (ev.key === 'Enter') save(); });
    input.addEventListener('input', () => setText(err, ''));
    input._update = force => {
      if (!force && document.activeElement === input) return;
      const n = parseFloat(store.get(id).value);
      input.value = isNum ? (isNaN(n) ? '' : n) : store.text(id);
    };
    input._update();
    const wrap = h('span', { class: 'field' }, input,
                   e.uom ? h('span', { class: 'unit' }, e.uom) : null,
                   h('button', { class: 'btn btn-small', 'aria-label': `Set ${label}`, onclick: save }, 'Set'), err);
    wrap._update = () => input._update();
    return wrap;
  }
  return null;
}

/** A settings row: label, explanation, and the entity's own control (limits and unit from the device). Nothing if
 *  the entity is not in this build. Returns the row; its control keeps itself current through ._update. */
function setting(label, hint, id) {
  const control = entityControl(id);
  if (!control) return null;
  const el = h('div', { class: 'setting' },
    h('div', { class: 'setting-text' }, h('div', { class: 'setting-label' }, label), hint ? h('div', { class: 'hint' }, hint) : null),
    h('div', { class: 'setting-control' }, control));
  el._update = () => { if (control._update) control._update(); };
  return el;
}

// ---- mechanisms.js ----
// What moves the tray (firmware 2.1.0). The device names its mechanism in the Mechanism entity; each one has a
// description here: its tray drawing, its wording, and its own calibration cards, as data. Layout and wording only:
// limits and behaviour come from the device. Adding a mechanism: AGENTS.md, "Adding a mechanism".

/** Portions per load, as the device reports it (6 from a firmware before 2.1.0, which has no Capacity). */
function capacity() {
  const c = store.num(E.capacity);
  return isNaN(c) || c < 1 ? 6 : c;
}

function svgEl(tag, attrs) {
  const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
  return e;
}

/** The middle of a dial: portions left, large, and a line under it. */
function dialCentre(svg, unknown, left, cap) {
  const big = svgEl('text', { x: 100, y: 102, class: 'dial-big', 'text-anchor': 'middle' });
  big.textContent = unknown ? '?' : String(left);
  const small = svgEl('text', { x: 100, y: 126, class: 'dial-small', 'text-anchor': 'middle' });
  small.textContent = unknown ? 'position unknown' : `of ${cap} left`;
  svg.appendChild(big);
  svg.appendChild(small);
}

const MECHANISMS = {
  servo: {
    /** The tray as seven slots on an arc: closed slot 0, slots already used, slots with food, and the current one. */
    dial(position, unknown) {
      const cap = capacity();
      const left = unknown ? null : Math.max(0, cap - position);
      const svg = svgEl('svg', { viewBox: '0 0 200 170', class: 'dial', role: 'img' });
      const title = svgEl('title', {});
      title.textContent = unknown ? 'Tray position unknown' : `Tray at slot ${position}: ${left} of ${cap} portions left`;
      svg.appendChild(title);
      svg.appendChild(svgEl('path', { d: 'M 37 136 A 74 74 0 1 1 163 136', class: 'dial-track' }));
      for (let i = 0; i <= cap; i++) {
        const a = (150 + i * 240 / cap) * Math.PI / 180;
        const x = 100 + 74 * Math.cos(a), y = 100 + 74 * Math.sin(a);
        let cls = 'slot-food';
        if (unknown) cls = 'slot-unknown';
        else if (i === 0) cls = 'slot-closed';
        else if (i <= position) cls = 'slot-used';
        if (!unknown && i === position) svg.appendChild(svgEl('circle', { cx: x, cy: y, r: 15, class: 'slot-ring' }));
        svg.appendChild(svgEl('circle', { cx: x, cy: y, r: i === 0 ? 8 : 10, class: `slot ${cls}` }));
      }
      dialCentre(svg, unknown, left, cap);
      return svg;
    },
    position: p => `Slot ${p}`,
    reloadText: cap => 'Press this before you load food. The tray turns back to the closed slot, so nothing can fall ' +
                       `out while you fill it, and all ${cap} portions count as available again.`,
    reloadDone: 'Tray going back to the closed slot',
    recoverText: cap => 'Look at the feeder and choose the slot that is over the opening. Slot 0 is the closed one; ' +
                        `each feed moves one slot further, up to ${cap}.`,
    recoverFallback: 'Not sure? Cancel and use Tray reload instead: it returns to the closed slot, which is always safe.',
    recoveryHint: 'Tell it which slot is over the opening, or reload the tray (it turns back to the closed slot, which ' +
                  'is always safe).',
    // The servo's calibration (slots, offsets, pulse range) is the Calibration card, shown whenever the build has a
    // Calibration Position. Cards a mechanism adds: {title, hint, settings: [[label, hint, E.x]], buttons: [[label,
    // E.x, done]], readings: [[label, E.x]]}.
    cards: [],
  },
};

MECHANISMS['n20-direct'] = {
  /** The disc as a ring: the slot over the chute at the bottom (always empty), slots with food, and slots used. */
  dial(position, unknown) {
    const cap = capacity(), slots = cap + 1;
    const left = unknown ? null : Math.max(0, cap - position);
    const svg = svgEl('svg', { viewBox: '0 0 200 170', class: 'dial', role: 'img' });
    const title = svgEl('title', {});
    title.textContent = unknown ? 'Disc position unknown' : `${left} of ${cap} portions left`;
    svg.appendChild(title);
    svg.appendChild(svgEl('circle', { cx: 100, cy: 85, r: 70, class: 'dial-track', fill: 'none' }));
    for (let i = 0; i < slots; i++) {
      // Slot 0 is over the chute; the next feed brings slot 1 there, and so on round the disc.
      const a = (90 + i * 360 / slots) * Math.PI / 180;
      const x = 100 + 70 * Math.cos(a), y = 85 + 70 * Math.sin(a);
      let cls = 'slot-used';
      if (unknown) cls = 'slot-unknown';
      else if (i === 0) cls = 'slot-closed';
      else if (i <= left) cls = 'slot-food';
      if (i === 0) svg.appendChild(svgEl('circle', { cx: x, cy: y, r: 12, class: 'slot-ring' }));
      svg.appendChild(svgEl('circle', { cx: x, cy: y, r: 7, class: `slot ${cls}` }));
    }
    dialCentre(svg, unknown, left, cap);
    return svg;
  },
  position: p => `${p} fed since reload`,
  reloadText: cap => `Fill every slot except the one over the chute, then press this: all ${cap} portions count again.`,
  reloadDone: 'Disc reloaded',
  recoverText: cap => `Portions fed since the disc was filled (0 to ${cap}). Centre a slot over the hole first.`,
  recoverFallback: 'Not sure? Cancel, refill the disc, then Tray reload.',
  recoveryHint: 'In calibration mode, nudge a slot over the hole, then declare the portions fed, or refill and reload.',
  cards: [
    { title: 'Calibration',
      hint: 'Turn Calibration mode on and follow Next step: it names each button. Empty the disc first.',
      settings: [['Calibration mode', 'Feeding is refused while it is on.', E.calibrationMode],
                 ['Disc slots', 'Slots on your disc, all open (a load holds one fewer). Calibration mode only.',
                  E.discSlots],
                 ['Slot trim', 'Set by Trim here (step 4): + further forward, − further back.',
                  E.slotTrim]],
      readings: [['Next step', E.calStep]],
      buttons: [['Start', E.calStart], ['Yes', E.calYes], ['No', E.calNo], ['Nudge 0.1°', E.calNudgeSmall],
                ['Nudge 1°', E.calNudgeLarge], ['Overshot', E.calOvershot], ['Zero', E.calZero],
                ['Run turns', E.calTurns], ['Measured', E.calMeasured], ['Next slot', E.calNext],
                ['Trim here', E.calTrimHere]] },
    { title: 'Encoder',
      settings: [['Ticks per turn', 'Encoder ticks for one turn of the disc; the calibration measures it.', E.ticksPerTurn],
                 ['Calibration turns', 'Turns the measurement spans: more is more accurate.', E.calibrationTurns],
                 ['Reverse motor', 'Set by the direction test.', E.reverseMotor],
                 ['Reverse encoder', 'Set by the direction test.', E.reverseEncoder]] },
    { title: 'Motion',
      settings: [['Drive power', '', E.drivePower],
                 ['Braking distance', 'Where it starts braking and creeping before each slot.', E.brakingDistance]] },
    { title: 'Wiggle',
      hint: 'Part of every feed: it shakes food loose and centres the slot.',
      settings: [['Amplitude', 'How far each side of the slot.', E.wiggleAmplitude],
                 ['Cycles', '', E.wiggleCycles]] },
    { title: 'Motor status',
      readings: [['Last fault', E.motorFault], ['Encoder ticks', E.encoderTicks], ['Longest control gap', E.motorLoopGap]] },
  ],
};

/** The description of the mechanism the device reports (the servo's for a firmware that reports none). */
function mechanism() {
  return MECHANISMS[store.text(E.mechanism)] || MECHANISMS.servo;
}

/** The mechanism's own calibration cards. Each control is the entity's own (setting()); a card none of whose entities
 *  this build has is left out. Pushes every row that needs updating into `rows` (each has ._update). */
function mechanismCards(rows) {
  const out = [];
  for (const c of mechanism().cards) {
    const items = (c.settings || []).map(([label, hint, id]) => setting(label, hint, id)).filter(Boolean);
    const reads = (c.readings || []).filter(([, id]) => store.has(id)).map(([label, id]) => {
      const r = row(label);
      r.row._update = () => setText(r.value, store.text(id));
      return r.row;
    });
    const buttons = (c.buttons || []).filter(([, id]) => store.has(id)).map(([label, id, done]) =>
      h('button', { class: 'btn', onclick: () => api.press(id).then(() => toast(done || label, 'ok'), toastError) }, label));
    if (!items.length && !reads.length && !buttons.length) continue;
    rows.push(...items, ...reads);
    out.push(card(c.title, c.hint ? h('p', { class: 'hint' }, c.hint) : null, ...items, ...reads,
      buttons.length ? h('div', { class: 'actions' }, buttons) : null));
  }
  return out;
}

// ---- banners.js ----
// The banner under the header: the most important thing wrong right now, with what you can do about it. One at a
// time, most severe first. Everything here comes from what the device reports (Tray State, Faults, Clock Valid,
// Hold, ...); the app never works out a fault for itself.

/** Before loading food: explain, then press Tray Reload. Shared with the Dashboard. */
async function trayReloadFlow() {
  const pause = store.num(E.reloadPause);
  const ok = await confirmDialog({
    title: 'Reload the tray?',
    body: h('div', {},
      h('p', {}, mechanism().reloadText(capacity())),
      h('p', {}, isNaN(pause) || pause === 0
        ? 'Scheduled feeding carries on straight away.'
        : `Scheduled feeding pauses for ${pause} min while you load it. Feeds due in that time are skipped, not made up.`)),
    ok: 'Reload tray',
  });
  if (!ok) return;
  api.press(E.trayReload).then(() => toast(mechanism().reloadDone, 'ok'), toastError);
}

/** After a power cut mid-feed: say which slot the tray is really on (Declared Tray Position, then Declare). */
async function recoverPositionFlow() {
  let chosen = null;
  const buttons = Array.from({ length: capacity() + 1 }, (_, i) => i).map(i => h('button', { type: 'button', class: 'btn slot-pick', 'aria-pressed': 'false',
    onclick: () => {
      chosen = i;
      for (const b of buttons) b.setAttribute('aria-pressed', b === buttons[i] ? 'true' : 'false');
    } }, String(i)));
  const ok = await confirmDialog({
    title: 'Where is the tray?',
    body: h('div', {},
      h('p', {}, mechanism().recoverText(capacity())),
      h('div', { class: 'slot-picker' }, buttons),
      h('p', {}, mechanism().recoverFallback)),
    ok: 'Set position',
  });
  if (!ok) return;
  if (chosen === null) {
    toast('Choose a slot first', 'error');
    return;
  }
  try {
    await api.setAndConfirm(E.declaredPosition, chosen);
    await api.press(E.declarePosition);
    await api.waitFor(E.trayState, e => e.value !== 'unknown', 3500);
    toast(`Tray set to slot ${chosen}`, 'ok');
  } catch (err) {
    toastError(err);
  }
}

/** Turn calibration mode off, which saves the offsets. */
function finishCalibration() {
  api.turn(E.calibrationMode, false)
    .then(() => api.waitFor(E.calibrationMode, x => x.value === false))
    .then(() => toast('Calibration saved', 'ok'), toastError);
}

/** A hold in words: "Until you resume it", "Until Sat, Oct 17 2:28 PM". */
function holdWords(hold) {
  if (hold.until) return `Until ${formatDate(hold.until)} ${formatClock(hold.until.hour, hold.until.minute)}`;
  if (hold.note) return hold.note[0].toUpperCase() + hold.note.slice(1);
  return 'Until you resume it';
}

/** The faults the banners below already explain, so they are not listed twice. */
const COVERED_FAULTS = ['clock not set', 'tray position unknown', 'tray empty', 'next feed needs more portions'];

/** After the feeder restarts, check whether it now serves a different app (it was updated); if so, offer a reload. */
const appUpdate = {
  available: false,
  check() {
    fetch(`${location.origin}/0.js`, { cache: 'no-store' })
      .then(r => (r.ok ? r.text() : ''))
      .then(text => {
        if (text && !text.includes(`const BUILD_ID = '${BUILD_ID}'`)) {
          this.available = true;
          banners.update();
        }
      })
      .catch(() => { /* checked again after the next restart */ });
  },
};

function currentBanner() {
  if (store.everOnline && store.status !== 'online' && store.status !== 'paused') {
    return { kind: 'neutral', icon: 'wifiOff', title: 'Connection lost',
             text: 'Reconnecting… The feeder keeps running on its own schedule.' };
  }
  if (appUpdate.available) {
    return { kind: 'info', icon: 'refresh', title: 'The feeder was updated',
             text: 'Reload this page to use the new version of the app.',
             actions: [{ label: 'Reload', run: () => location.reload() }] };
  }
  if (!store.has(E.trayState)) return null;
  const tray = store.text(E.trayState);
  if (tray === 'unknown') {
    return { kind: 'danger', icon: 'alert', title: 'Tray position unknown',
             text: 'Feeding is off until you tell the feeder where the tray is, or reload it.',
             actions: [
               store.has(E.declarePosition) && store.has(E.declaredPosition)
                 ? { label: 'Recover position', run: recoverPositionFlow } : null,
               { label: 'Tray reload', run: trayReloadFlow },
             ] };
  }
  if (tray === 'calibrating') {
    return { kind: 'warning', icon: 'tune', title: 'Calibration mode is on', text: 'All feeds are refused until you finish.',
             actions: store.has(E.calibrationMode) ? [{ label: 'Finish and save', run: finishCalibration }] : [] };
  }
  if (tray === 'empty') {
    return { kind: 'danger', icon: 'bowl', title: 'Tray empty',
             text: 'Reload the tray, then load food.', actions: [{ label: 'Tray reload', run: trayReloadFlow }] };
  }
  if (store.bool(E.clockValid) === false) {
    return { kind: 'warning', icon: 'clock', title: 'Clock not set',
             text: 'Scheduled feeds wait until the feeder knows the time. Feeding by hand still works.' };
  }
  if (store.bool(E.needsFood)) {
    return { kind: 'warning', icon: 'fish', title: 'The next feed needs more than remains',
             text: `${store.num(E.portionsRemaining)} left. Refill before ${store.text(E.nextFeed)}.`,
             actions: [{ label: 'Tray reload', run: trayReloadFlow }] };
  }
  const hold = parseHold(store.text(E.hold));
  if (hold) {
    return { kind: 'info', icon: 'pause', title: 'Scheduled feeding on hold',
             text: `${holdWords(hold)}. Missed feeds are skipped, not made up.`,
             actions: store.has(E.cancelHold) ? [{ label: 'Resume now', run: () => api.press(E.cancelHold)
               .then(() => toast('Scheduled feeding resumed', 'ok'), toastError) }] : [] };
  }
  const other = parseList(store.text(E.faults)).filter(f => !COVERED_FAULTS.some(c => f.startsWith(c)));
  if (other.length) {
    return { kind: 'warning', icon: 'alert', title: other.length === 1 ? 'One thing to check' : `${other.length} things to check`,
             list: other.map(f => f[0].toUpperCase() + f.slice(1)) };
  }
  return null;
}

const banners = {
  el: null,
  key: '',
  mount(el) { this.el = el; },
  update() {
    const b = currentBanner();
    const key = b ? JSON.stringify([b.kind, b.title, b.text, b.list, (b.actions || []).filter(Boolean).map(a => a.label)]) : '';
    if (key === this.key) return;
    this.key = key;
    clear(this.el);
    if (!b) return;
    this.el.appendChild(h('div', { class: `banner banner-${b.kind}`, role: b.kind === 'danger' ? 'alert' : 'status' },
      icon(b.icon, 22),
      h('div', { class: 'banner-body' },
        h('strong', {}, b.title),
        b.text ? h('p', {}, b.text) : null,
        b.list ? h('ul', {}, b.list.map(f => h('li', {}, f))) : null,
        (b.actions || []).filter(Boolean).length
          ? h('div', { class: 'banner-actions' }, b.actions.filter(Boolean).map(a => h('button', { class: 'btn btn-small', onclick: a.run }, a.label)))
          : null)));
  },
};

// ---- pages/dashboard.js ----
// Dashboard: the tray, the next feed, Feed now, today's feeds, status and the everyday actions. Everything shown
// is what the device reports; Feed now asks the device, whose guard decides, and reports the device's answer.

const STATUS_WORDS = {
  fed: ['check', 'Fed'], skipped: ['x', 'Skipped'], due: ['clock', 'Due now'], next: ['clock', 'Next'],
  later: ['clock', 'Later'], held: ['pause', 'On hold'],
};
const HOLD_CHOICES = [[2, '2 hours'], [12, '12 hours'], [24, '1 day'], [72, '3 days'], [168, '1 week'], [0, 'Until I resume it']];

PAGES.dashboard = {
  mount(root) {
    this.portions = 1;
    this.updaters = [];
    this.keys = {};

    // ---- hero: tray, next feed, runway, Feed now ----
    this.dialBox = h('div', { class: 'dial-box' });
    this.nextTime = h('div', { class: 'stat-big' });
    this.nextSub = h('div', { class: 'stat-sub' });
    this.runwayBig = h('div', { class: 'stat-big' });
    this.runwaySub = h('div', { class: 'stat-sub' });
    this.guardPill = h('span', { class: 'pill' });
    this.stepper = h('div', { class: 'stepper', hidden: true },
      h('button', { class: 'btn btn-small', 'aria-label': 'One portion less', onclick: () => this.step(-1) }, '−'),
      this.stepValue = h('span', { class: 'stepper-value', 'aria-live': 'polite' }, '1'),
      h('button', { class: 'btn btn-small', 'aria-label': 'One portion more', onclick: () => this.step(1) }, '+'));
    this.feedBtn = h('button', { class: 'btn btn-primary btn-feed', onclick: () => this.feedNow() }, icon('fish', 20), 'Feed now');
    const hero = h('section', { class: 'card hero' },
      this.dialBox,
      h('div', { class: 'hero-side' },
        h('div', { class: 'stats' },
          h('div', {}, h('div', { class: 'stat-label' }, 'Next feed'), this.nextTime, this.nextSub),
          h('div', {}, h('div', { class: 'stat-label' }, 'Runway'), this.runwayBig, this.runwaySub)),
        h('div', { class: 'feed-row' }, this.stepper, this.feedBtn),
        h('div', { class: 'guard' }, this.guardPill)));

    // ---- today ----
    this.todayTitle = h('h2', { class: 'card-title' }, 'Today');
    this.todayList = h('div', { class: 'today' });
    this.scheduleLink = h('a', { class: 'card-link', href: '#schedule', hidden: true }, 'Schedule');
    const today = h('section', { class: 'card' }, h('div', { class: 'card-head' }, this.todayTitle, this.scheduleLink),
                    this.todayList);

    // ---- status ----
    const status = card('Status');
    const add = (label, fn) => this.updaters.push(boundRow(status, label, fn));
    add('Schedule', () => {
      if (store.has(E.scheduler) && store.bool(E.scheduler) === false) return 'Off';
      if (parseHold(store.text(E.hold))) return 'On hold';
      return 'Running';
    });
    add('Tray', () => {
      const state = store.text(E.trayState);
      return state === 'unknown' ? 'Position unknown' : `${mechanism().position(store.num(E.trayPosition))}, ${state}`;
    });
    add('Fed in the last 24 h', () => {
      const n = store.num(E.portions24h), cap = store.num(E.dailyCap);
      if (isNaN(n)) return `${store.num(E.fedToday)} today`;
      return isNaN(cap) ? `${n}` : `${n} of ${cap} allowed`;
    });
    add('Last feed', () => {
      const l = parseLastFeed(store.text(E.lastFeed));
      if (!l.when) return l.note || '';
      return `${this.when(l.when)}${l.source ? `, ${sourceLabel(l.source)}` : ''}`;
    });
    add('Clock', () => {
      if (store.bool(E.clockValid) === false) return 'Not set';
      const age = store.num(E.clockAge);
      return [store.text(E.timeSource), isNaN(age) ? '' : `synced ${formatDuration(age * 60) || 'just now'} ago`]
        .filter(Boolean).join(', ');
    });

    // ---- recent feeds ----
    this.recentList = h('div', { class: 'recent' });
    const recent = card('Recent feeds', this.recentList);

    // ---- actions ----
    this.holdText = h('p', { class: 'hint' });
    this.holdBtn = h('button', { class: 'btn', onclick: () => this.holdOrResume() });
    this.stopBtn = h('button', { class: 'btn btn-danger', hidden: true, onclick: () => api.press(E.stop)
      .then(() => toast('Stopped', 'ok'), toastError) }, 'Stop');
    const actions = card('Actions',
      h('div', { class: 'actions' },
        h('button', { class: 'btn', onclick: trayReloadFlow }, 'Tray reload'),
        store.has(E.holdFeeding) ? this.holdBtn : null,
        this.stopBtn),
      this.holdText);

    append(root, hero, h('div', { class: 'grid' }, today, status, recent, actions));
    this.update(new Set(['*all']));
  },

  /** The device's "today" (from Device Time), so "today" and "tomorrow" follow the feeder's clock, not the browser's. */
  today() {
    return parseDeviceTime(store.text(E.deviceTime));
  },
  /** A device date and time as "17:30", "tomorrow 08:00" or "Thu 15 Oct 08:00". */
  when(parts) {
    const rel = relativeDay(parts, this.today());
    const clock = formatClock(parts.hour, parts.minute);
    if (rel === 'today') return clock;
    return `${rel || formatDate(parts)} ${clock}`;
  },

  update() {
    for (const u of this.updaters) u();
    this.updateHero();
    this.updateToday();
    this.updateRecent();
    this.updateActions();
  },

  changed(name, value) {
    const key = JSON.stringify(value);
    if (this.keys[name] === key) return false;
    this.keys[name] = key;
    return true;
  },

  updateHero() {
    const state = store.text(E.trayState);
    const position = store.num(E.trayPosition);
    if (this.changed('dial', [state, position])) {
      clear(this.dialBox);
      this.dialBox.appendChild(mechanism().dial(position, state === 'unknown' || isNaN(position)));
    }
    // Next feed
    const next = parseLocalDateTime(store.text(E.nextFeed));
    if (next) {
      setText(this.nextTime, formatClock(next.hour, next.minute));
      const rel = relativeDay(next, this.today());
      const today = parseTodaysFeeds(store.text(E.todaysFeeds));
      const item = rel === 'today' && today ? today.items.find(i => i.time === next.time && i.status !== 'fed') : null;
      const portions = item ? `${item.portions} portion${item.portions === 1 ? '' : 's'}` : '';
      setText(this.nextSub, [rel ? rel[0].toUpperCase() + rel.slice(1) : formatDate(next), portions].filter(Boolean).join(', '));
    } else {
      const raw = store.text(E.nextFeed);
      setText(this.nextTime, '—');
      setText(this.nextSub, raw === 'none' ? 'Nothing scheduled' : raw === 'clock not set' ? 'Clock not set' : raw);
    }
    // Runway
    const runway = store.num(E.runway);
    const emptyOn = store.text(E.emptyOn);
    const empty = parseLocalDateTime(emptyOn);
    if (store.num(E.portionsRemaining) === 0) {
      setText(this.runwayBig, 'Empty');
      setText(this.runwaySub, 'Reload the tray');
    } else if (!isNaN(runway)) {
      setText(this.runwayBig, runway < 1 ? 'Under a day' : `${runway} day${runway === 1 ? '' : 's'}`);
      setText(this.runwaySub, empty ? `Empty ${this.when(empty)}` : '');
    } else {
      setText(this.runwayBig, emptyOn === 'not within 30 days' ? '30+ days' : '—');
      setText(this.runwaySub, emptyOn === 'clock not set' ? 'Clock not set' : '');
    }
    // Portions stepper, only when one command may feed more than one portion
    const max = store.num(E.maxPerCommand);
    const multi = max > 1 && store.has(E.feedSelected) && store.has(E.manualPortions);
    this.stepper.hidden = !multi;
    if (!multi) this.portions = 1;
    else this.portions = Math.min(this.portions, max);
    setText(this.stepValue, String(this.portions));
    setText(this.feedBtn.lastChild, this.portions > 1 ? `Feed ${this.portions} portions` : 'Feed now');
    // What the guard would say right now
    const guard = store.text(E.feedGuard);
    if (!store.has(E.feedGuard)) {
      this.guardPill.hidden = true;
    } else {
      this.guardPill.hidden = false;
      const ready = guard === 'ready';
      setText(this.guardPill, ready ? 'Ready to feed' : guard ? guard[0].toUpperCase() + guard.slice(1) : '');
      this.guardPill.className = `pill ${ready ? 'pill-ok' : 'pill-warn'}`;
    }
  },

  step(delta) {
    const max = store.num(E.maxPerCommand) || 1;
    this.portions = Math.min(max, Math.max(1, this.portions + delta));
    this.updateHero();
  },

  async feedNow() {
    const portions = this.portions;
    const guard = store.text(E.feedGuard);
    const ok = await confirmDialog({
      title: portions > 1 ? `Feed ${portions} portions now?` : 'Feed one portion now?',
      body: guard && guard !== 'ready'
        ? `Right now the feeder would refuse it: ${guard}. You can still ask; it checks again.`
        : 'The feeder checks it against its safety limits first.',
      ok: 'Feed',
    });
    if (!ok) return;
    const before = [store.text(E.lastResult), store.text(E.recentFeeds)];
    try {
      if (portions > 1) {
        await api.setAndConfirm(E.manualPortions, portions);
        await api.press(E.feedSelected);
      } else {
        await api.press(E.feedOne);
      }
    } catch (err) {
      toastError(err);
      return;
    }
    // The device reports its answer as Last Result (a refusal) or a new Recent Feeds entry (a feed). A refusal
    // repeated unchanged produces no update, so after a while its current Last Result is the answer.
    await api.waitForChange([E.lastResult, E.recentFeeds],
      () => store.text(E.lastResult) !== before[0] || store.text(E.recentFeeds) !== before[1], 3500);
    const result = store.text(E.lastResult);
    if (store.text(E.recentFeeds) !== before[1] || result === 'ok') toast(portions > 1 ? `Feeding ${portions} portions` : 'Feeding one portion', 'ok');
    else toast(`The feeder refused: ${result}`, 'error', 6000);
  },

  updateToday() {
    const profile = store.text(E.activeProfile);
    setText(this.todayTitle, profile ? `Today · Profile ${profile}` : 'Today');
    this.scheduleLink.hidden = !(PAGES.schedule && store.has(E.editProfile));
    const raw = store.text(E.todaysFeeds);
    if (!this.changed('today', raw)) return;
    clear(this.todayList);
    if (!store.has(E.todaysFeeds)) return;
    const t = parseTodaysFeeds(raw);
    if (!t) {
      this.todayList.appendChild(h('p', { class: 'hint' }, raw));
      return;
    }
    if (!t.items.length) {
      const notes = { 'fast day': 'No feeds today: it is a fast day.', 'not a feeding day': 'No feeds today: not a feeding day in this cycle.',
                      'scheduler off': 'The schedule is off.', 'clock not set': 'Waiting for the clock.' };
      this.todayList.appendChild(h('p', { class: 'hint' }, notes[t.note] || 'Nothing scheduled today.'));
      return;
    }
    for (const it of t.items) {
      const [ic, word] = STATUS_WORDS[it.status] || ['clock', it.status];
      this.todayList.appendChild(h('div', { class: `today-item today-${it.status}` },
        h('span', { class: 'today-icon' }, icon(ic, 18)),
        h('span', { class: 'today-time' }, formatClock(it.hour, it.minute)),
        h('span', { class: 'today-what' }, `${it.portions} portion${it.portions === 1 ? '' : 's'}`,
          it.oneshot ? h('span', { class: 'tag' }, 'one-shot') : null),
        h('span', { class: 'today-status' }, word)));
    }
  },

  updateRecent() {
    const raw = store.text(E.recentFeeds);
    if (!this.changed('recent', raw)) return;
    clear(this.recentList);
    const feeds = parseRecentFeeds(raw);
    if (!feeds.length) {
      this.recentList.appendChild(h('p', { class: 'hint' }, raw && raw !== 'none' ? raw : 'No feeds yet.'));
      return;
    }
    const year = (this.today() || { year: new Date().getFullYear() }).year;
    for (const f of feeds) {
      const when = f.month === null ? 'Time unknown'
        : this.when({ year, month: f.month, day: f.day, hour: f.hour, minute: f.minute });
      this.recentList.appendChild(h('div', { class: 'row' },
        h('span', { class: 'row-label' }, when),
        h('span', { class: 'row-value' }, `${f.portions} × ${sourceLabel(f.source)}`)));
    }
  },

  updateActions() {
    const hold = parseHold(store.text(E.hold));
    setText(this.holdBtn, hold ? 'Resume schedule' : 'Hold feeding');
    setText(this.holdText, hold ? `On hold: ${holdWords(hold).toLowerCase()}. Feeding by hand still works.` : '');
    this.stopBtn.hidden = store.text(E.trayState) !== 'moving';
  },

  async holdOrResume() {
    if (parseHold(store.text(E.hold))) {
      api.press(E.cancelHold).then(() => toast('Scheduled feeding resumed', 'ok'), toastError);
      return;
    }
    const choices = HOLD_CHOICES.map(([hours, label], i) => h('label', { class: 'choice' },
      h('input', { type: 'radio', name: 'hold', value: String(hours), checked: i === 2 }), label));
    const ok = await confirmDialog({
      title: 'Hold scheduled feeding',
      body: h('div', {}, h('p', {}, 'Scheduled and one-shot feeds are skipped while on hold, and not made up afterwards. ' +
                                   'Feeding by hand still works.'), h('div', { class: 'choices' }, choices)),
      ok: 'Hold',
    });
    if (!ok) return;
    const hours = +choices.map(c => c.firstChild).find(r => r.checked).value;
    try {
      await api.setAndConfirm(E.holdDuration, hours);
      await api.press(E.holdFeeding);
      await api.waitFor(E.hold, e => e.value && e.value !== 'none', 3500);
      toast('Scheduled feeding on hold', 'ok');
    } catch (err) {
      toast(store.bool(E.clockValid) === false && hours
        ? 'A timed hold needs the clock. Choose "Until I resume it" instead.' : err.message, 'error', 6000);
    }
  },
};

// ---- pages/schedule.js ----
// Schedule: the three profiles and their events, the scheduler switch, and one-shot feeds. The whole schedule is
// read from Schedule Data, so looking at a profile never moves the editor that Home Assistant shares. Changes go
// through the firmware's editor entities in the order docs/SCHEDULING.md gives, each confirmed by the device's
// echo, and are checked against Schedule Data at the end.

const PROFILE_KEYS = ['A', 'B', 'C'];
const ANCHOR_WORDS = { clock: 'Clock time', sunrise: 'Sunrise', sunset: 'Sunset' };

/** "08:30", "Sunset − 0:30", "Sunrise + 1:15". */
function eventWhen(ev) {
  if (ev.anchor === 'clock') return formatClock(Math.floor(ev.offset / 60), ev.offset % 60);
  const a = Math.abs(ev.offset);
  const base = ANCHOR_WORDS[ev.anchor];
  if (a === 0) return `At ${base.toLowerCase()}`;
  return `${base} ${ev.offset < 0 ? '−' : '+'} ${Math.floor(a / 60)}:${String(a % 60).padStart(2, '0')}`;
}

function sameEvent(a, b) {
  return a && b && a.enabled === b.enabled && a.anchor === b.anchor && a.offset === b.offset &&
         a.portions === b.portions && (a.days & 0x7f) === (b.days & 0x7f);
}

/** Point the firmware's editor at profile p (0..2) and, if given, event e (0..3). Cheap when it already is, so it
 *  is called again before every field write: Home Assistant shares this editor and may have moved it meanwhile. */
async function editorAt(p, e) {
  if (store.text(E.editProfile) !== PROFILE_KEYS[p]) await api.setAndConfirm(E.editProfile, PROFILE_KEYS[p]);
  if (e !== undefined && store.text(E.editEvent) !== String(e + 1)) await api.setAndConfirm(E.editEvent, String(e + 1));
}

/** Everything other than event e of profile p (e = -1: profile p's own settings) that differs from `before`. */
function othersChanged(before, p, e) {
  const after = parseScheduleData(store.text(E.scheduleData));
  const moved = [];
  if (!before || !after) return moved;
  before.forEach((prof, pi) => {
    if (pi !== p && (prof.everyN !== after[pi].everyN || prof.fast !== after[pi].fast)) moved.push(`profile ${PROFILE_KEYS[pi]} settings`);
    prof.events.forEach((ev, ei) => {
      if ((pi !== p || ei !== e) && !sameEvent(ev, after[pi].events[ei])) moved.push(`profile ${PROFILE_KEYS[pi]} event ${ei + 1}`);
    });
  });
  return moved;
}

function collisionMessage(moved) {
  return `Someone else used the schedule editor at the same time, and ${moved.join(', ')} changed too. ` +
         'Check it before relying on the schedule.';
}

/** Run a schedule save, then make sure nothing else changed: Home Assistant shares the editor, and if it moved the
 *  editor in the middle of the save a write may have landed on another event. That is reported by name, also when
 *  the save itself failed (a write that landed elsewhere is not confirmed where it was meant to go). */
async function guardedSave(p, e, task) {
  const before = parseScheduleData(store.text(E.scheduleData));
  try {
    await task();
  } catch (err) {
    // Give a stray write's result time to show in Schedule Data (published within about a second).
    await api.waitForChange([E.scheduleData], () => othersChanged(before, p, e).length > 0, 1500);
    const moved = othersChanged(before, p, e);
    throw moved.length ? new Error(`${err.message} ${collisionMessage(moved)}`) : err;
  }
  const moved = othersChanged(before, p, e);
  if (moved.length) throw new Error(collisionMessage(moved));
}

PAGES.schedule = {
  mount(root, sub) {
    const want = PROFILE_KEYS.indexOf((sub || '').toUpperCase());
    const active = PROFILE_KEYS.indexOf(store.text(E.activeProfile));
    this.view = want >= 0 ? want : Math.max(0, active);
    this.busy = false;
    this.keys = {};

    this.tabs = h('div', { class: 'profile-tabs', role: 'tablist', 'aria-label': 'Profiles' });
    this.head = h('div', { class: 'profile-head' });
    this.events = h('div', { class: 'events' });
    this.warn = h('div', {});
    const profileCard = h('section', { class: 'card' }, this.tabs, this.head, this.warn, this.events);

    this.schedulerRow = h('div', { class: 'row' });
    const general = card('Schedule', this.schedulerRow,
      h('p', { class: 'hint' }, 'Changes reach the feeder straight away. The editor is shared with Home Assistant: its ' +
                                 'Edit Profile and Edit Event follow what you change here.'));

    this.oneshotList = h('div', { class: 'oneshots' });
    const oneshots = card('One-shot feeds',
      h('p', { class: 'hint' }, 'A single feed on a given date. These run even with the schedule off, but not during a hold.'),
      this.oneshotList,
      h('div', { class: 'actions' },
        h('button', { class: 'btn', onclick: () => this.addOneshot() }, 'Add one-shot feed'),
        this.clearBtn = h('button', { class: 'btn', onclick: () => this.clearOneshots() }, 'Clear all')));

    append(root, profileCard, h('div', { class: 'grid' }, general, oneshots));
    this.update(new Set(['*all']));
  },

  changed(name, value) {
    const key = JSON.stringify(value);
    if (this.keys[name] === key) return false;
    this.keys[name] = key;
    return true;
  },

  profiles() {
    return parseScheduleData(store.text(E.scheduleData));
  },

  update() {
    const profiles = this.profiles();
    const active = PROFILE_KEYS.indexOf(store.text(E.activeProfile));
    const scheduler = store.bool(E.scheduler);
    if (this.changed('profile', [store.text(E.scheduleData), active, scheduler, this.view, store.text(E.editedProfile),
                                 store.text(E.faults)])) {
      this.renderProfile(profiles, active, scheduler);
    }
    if (this.changed('scheduler', scheduler)) this.renderScheduler(scheduler);
    if (this.changed('oneshots', store.text(E.oneshots))) this.renderOneshots();
  },

  renderProfile(profiles, active, scheduler) {
    clear(this.tabs);
    PROFILE_KEYS.forEach((k, i) => {
      this.tabs.appendChild(h('button', { class: i === this.view ? 'ptab ptab-on' : 'ptab', role: 'tab',
        'aria-selected': i === this.view ? 'true' : 'false', onclick: () => this.show(i) },
        `Profile ${k}`, i === active ? h('span', { class: 'ptab-active' }, 'Active') : null));
    });
    clear(this.head);
    clear(this.warn);
    clear(this.events);
    if (!profiles) {
      this.events.appendChild(h('p', { class: 'hint' }, store.has(E.scheduleData)
        ? 'This firmware reports the schedule in a newer format than this page understands.'
        : 'Waiting for the feeder…'));
      return;
    }
    const p = profiles[this.view];
    const isActive = this.view === active;
    const cadence = p.everyN === 1 ? 'Every day' : p.everyN === 2 ? 'Every second day' : `Every ${p.everyN} days`;
    append(this.head,
      h('div', { class: 'profile-facts' },
        h('span', {}, cadence),
        h('span', {}, p.fast ? `Fast days: ${daysWords(p.fast)}` : 'No fast days')),
      h('div', { class: 'actions' },
        h('button', { class: 'btn btn-small', onclick: () => this.editProfile() }, 'Cadence and fast days'),
        isActive ? null : h('button', { class: 'btn btn-small btn-primary', onclick: () => this.makeActive() },
                              `Make profile ${PROFILE_KEYS[this.view]} active`)));
    // Warnings: the firmware's own, for this profile (Edited Profile when the editor is on it; Faults for the active one).
    const notes = [];
    const edited = store.text(E.editedProfile);
    if (store.text(E.editProfile) === PROFILE_KEYS[this.view] && edited.includes(' ! ')) notes.push(edited.split(' ! ')[1]);
    if (isActive) {
      for (const f of parseList(store.text(E.faults))) {
        if (f.startsWith('schedule ') || f.startsWith('sunrise') || f.startsWith('no sunrise')) notes.push(f);
      }
      if (scheduler === false) notes.push('the schedule is off, so this profile is not running');
    } else {
      notes.push('not running: only the active profile feeds');
    }
    if (notes.length) {
      this.warn.appendChild(h('ul', { class: isActive ? 'notes notes-warn' : 'notes' },
        notes.map(n => h('li', {}, n[0].toUpperCase() + n.slice(1)))));
    }
    p.events.forEach((ev, i) => {
      this.events.appendChild(h('div', { class: ev.enabled ? 'event' : 'event event-off' },
        h('span', { class: 'event-num' }, String(i + 1)),
        h('div', { class: 'event-main' },
          h('div', { class: 'event-when' }, eventWhen(ev)),
          h('div', { class: 'event-sub' }, `${ev.portions} portion${ev.portions === 1 ? '' : 's'}`,
            h('span', { class: 'sr-only' }, `, ${daysWords(ev.days)}`))),
        dayChips(ev.days, false, `Event ${i + 1} days`),
        h('button', { class: ev.enabled ? 'btn btn-small btn-on' : 'btn btn-small', role: 'switch',
                      'aria-checked': ev.enabled ? 'true' : 'false', 'aria-label': `Event ${i + 1} on`,
                      onclick: () => this.toggleEvent(i, !ev.enabled) }, ev.enabled ? 'On' : 'Off'),
        h('button', { class: 'btn btn-small', onclick: () => this.editEvent(i) }, 'Edit')));
    });
  },

  show(i) {
    this.view = i;
    history.replaceState(null, '', `#schedule/${PROFILE_KEYS[i].toLowerCase()}`);
    this.update();
  },

  renderScheduler(on) {
    clear(this.schedulerRow);
    append(this.schedulerRow,
      h('span', { class: 'row-label' }, 'Scheduled feeding'),
      h('button', { class: on ? 'btn btn-small btn-on' : 'btn btn-small', role: 'switch', 'aria-checked': on ? 'true' : 'false',
                    onclick: () => this.setScheduler(!on) }, on ? 'On' : 'Off'));
  },

  async setScheduler(on) {
    if (!on && !await confirmDialog({ title: 'Turn the schedule off?',
      body: 'No profile feeds until you turn it back on. One-shot feeds and feeding by hand still work.', ok: 'Turn off' })) return;
    this.run(() => api.turnAndConfirm(E.scheduler, on), on ? 'Schedule on' : 'Schedule off');
  },

  async makeActive() {
    const k = PROFILE_KEYS[this.view];
    if (!await confirmDialog({ title: `Make profile ${k} active?`,
      body: `The feeder follows profile ${k} from now on. Feeds already done today still count towards the daily cap.`,
      ok: `Use profile ${k}` })) return;
    this.run(() => api.setAndConfirm(E.activeProfile, k), `Profile ${k} is active`);
  },

  /** Run a change once at a time, reporting the outcome. */
  async run(task, done) {
    if (this.busy) {
      toast('Still saving the last change…');
      return;
    }
    this.busy = true;
    try {
      await task();
      if (done) toast(done, 'ok');
    } catch (err) {
      toastError(err);
    } finally {
      this.busy = false;
    }
  },

  async toggleEvent(i, on) {
    const p = this.view;
    this.run(() => guardedSave(p, i, async () => {
      await editorAt(p, i);
      await api.turnAndConfirm(E.eventEnabled, on);
      await api.waitFor(E.scheduleData, x => {
        const s = parseScheduleData(x.value);
        return s && s[p].events[i].enabled === on;
      }, 4000).catch(() => { throw new Error(`Event ${i + 1} did not end up ${on ? 'on' : 'off'}. Check it and try again.`); });
    }), `Event ${i + 1} ${on ? 'on' : 'off'}`);
  },

  async editEvent(i) {
    const profiles = this.profiles();
    if (!profiles) return;
    const p = this.view;
    const cur = profiles[p].events[i];
    const portionsEntity = store.get(E.eventPortions) || {};
    const lo = parseInt(portionsEntity.min_value, 10) || 1, hi = parseInt(portionsEntity.max_value, 10) || 6;

    const enabled = h('input', { type: 'checkbox', checked: cur.enabled });
    const clockTime = h('input', { type: 'time', class: 'input', step: '60', required: true,
      value: cur.anchor === 'clock' ? eventTimeText('clock', cur.offset) : '08:00' });
    const a = cur.anchor === 'clock' ? 0 : Math.abs(cur.offset);
    const dir = segmented([['before', 'Before'], ['after', 'After']], cur.anchor !== 'clock' && cur.offset < 0 ? 'before' : 'after', 'Before or after');
    const hours = h('input', { type: 'number', class: 'input input-num', min: 0, max: 12, step: 1, value: Math.floor(a / 60), 'aria-label': 'Hours' });
    const minutes = h('input', { type: 'number', class: 'input input-num', min: 0, max: 59, step: 1, value: a % 60, 'aria-label': 'Minutes' });
    const sunBox = h('div', { class: 'sun-offset' }, dir, hours, h('span', {}, 'h'), minutes, h('span', {}, 'min'));
    const clockField = field('Time', clockTime, 'The feeder’s local time.');
    const sunField = field('How long', sunBox, 'Up to 12 hours. Set the location under Configuration.');
    const showTime = anchor => {
      clockField.hidden = anchor !== 'clock';
      sunField.hidden = anchor === 'clock';
    };
    const anchor = segmented([['clock', 'Clock time'], ['sunrise', 'Sunrise'], ['sunset', 'Sunset']], cur.anchor, 'When', showTime);
    showTime(cur.anchor);
    const portions = stepper(cur.portions, lo, hi, 'Portions');
    const days = dayChips(cur.days, true, 'Days');

    const wanted = () => {
      let offset;
      if (anchor.value === 'clock') {
        const [hh, mm] = (clockTime.value || '').split(':').map(Number);
        offset = hh * 60 + mm;
      } else {
        offset = (parseInt(hours.value, 10) || 0) * 60 + (parseInt(minutes.value, 10) || 0);
        if (dir.value === 'before') offset = -offset;
      }
      return { enabled: enabled.checked, anchor: anchor.value, offset, portions: portions.value, days: days.mask };
    };
    const ok = await formDialog({
      title: `Profile ${PROFILE_KEYS[p]}, event ${i + 1}`,
      body: [
        h('label', { class: 'check' }, enabled, 'Feed at this time'),
        field('When', anchor), clockField, sunField,
        field('Portions', portions),
        field('Days', days)],
      validate: () => {
        const w = wanted();
        if (w.anchor === 'clock' && !/^\d{2}:\d{2}/.test(clockTime.value)) return 'Enter a time.';
        if (w.anchor !== 'clock') {
          const hh = parseInt(hours.value, 10) || 0, mm = parseInt(minutes.value, 10) || 0;
          if (hh < 0 || mm < 0 || mm > 59 || Math.abs(w.offset) > 720) return 'Up to 12 hours before or after.';
        }
        if (w.enabled && !w.days) return 'Choose at least one day, or turn the event off.';
        return '';
      },
    });
    if (!ok) return;
    const want = wanted();
    if (sameEvent(cur, want)) return;
    this.run(() => guardedSave(p, i, async () => {
      // Each write re-points the shared editor first (see editorAt).
      const write = async step => {
        await editorAt(p, i);
        await step();
      };
      // The editor applies each field at once. Switch a live event off before moving it, so it can never fire
      // half-changed; a failure part-way then leaves it off (the safe side), not wrong.
      const moves = cur.anchor !== want.anchor || cur.offset !== want.offset || cur.days !== want.days;
      if (cur.enabled && moves) await write(() => api.turnAndConfirm(E.eventEnabled, false));
      if (cur.anchor !== want.anchor) await write(() => api.setAndConfirm(E.eventAnchor, want.anchor));
      // A new anchor resets the time on the device, so write the time whenever either changed.
      if (cur.anchor !== want.anchor || cur.offset !== want.offset) {
        await write(() => api.setAndConfirm(E.eventTime, eventTimeText(want.anchor, want.offset)));
      }
      if (cur.days !== want.days) await write(() => api.setAndConfirm(E.eventDays, daysText(want.days)));
      if (cur.portions !== want.portions) await write(() => api.setAndConfirm(E.eventPortions, want.portions));
      await editorAt(p, i);
      if (store.bool(E.eventEnabled) !== want.enabled) await api.turnAndConfirm(E.eventEnabled, want.enabled);
      await api.waitFor(E.scheduleData, x => {
        const s = parseScheduleData(x.value);
        return s && sameEvent(s[p].events[i], want);
      }, 4000).catch(() => { throw new Error(`Event ${i + 1} did not end up as set. Check it and try again.`); });
    }), `Event ${i + 1} saved`);
  },

  async editProfile() {
    const profiles = this.profiles();
    if (!profiles) return;
    const p = this.view;
    const cur = profiles[p];
    const n = store.get(E.everyNDays) || {};
    const lo = parseInt(n.min_value, 10) || 1, hi = parseInt(n.max_value, 10) || 14;
    const every = h('select', { class: 'input', 'aria-label': 'How often' });
    for (let k = lo; k <= hi; k++) {
      every.appendChild(h('option', { value: String(k), selected: k === cur.everyN },
        k === 1 ? 'Every day' : k === 2 ? 'Every second day' : `Every ${k} days`));
    }
    const restart = h('input', { type: 'checkbox' });
    const restartField = h('label', { class: 'check' }, restart, 'Start the cycle today (today becomes a feeding day)');
    const showRestart = () => { restartField.hidden = +every.value === 1; };
    every.addEventListener('change', showRestart);
    showRestart();
    const fast = dayChips(cur.fast, true, 'Fast days');
    const ok = await formDialog({
      title: `Profile ${PROFILE_KEYS[p]}: cadence and fast days`,
      body: [field('How often', every), restartField,
             field('Fast days', fast, 'Weekdays with no feeding at all in this profile.')],
    });
    if (!ok) return;
    const everyN = +every.value;
    if (everyN === cur.everyN && fast.mask === cur.fast && !restart.checked) return;
    this.run(() => guardedSave(p, -1, async () => {
      if (everyN !== cur.everyN) {
        await editorAt(p);
        await api.setAndConfirm(E.everyNDays, everyN);
      }
      if (fast.mask !== cur.fast) {
        await editorAt(p);
        await api.setAndConfirm(E.fastDays, daysText(fast.mask));
      }
      if (restart.checked && everyN > 1) {
        await editorAt(p);
        await api.press(E.restartCycle);
      }
      await api.waitFor(E.scheduleData, x => {
        const s = parseScheduleData(x.value);
        return s && s[p].everyN === everyN && s[p].fast === fast.mask;
      }, 4000).catch(() => { throw new Error('The profile did not end up as set. Check it and try again.'); });
    }), `Profile ${PROFILE_KEYS[p]} saved`);
  },

  renderOneshots() {
    clear(this.oneshotList);
    const list = parseOneshots(store.text(E.oneshots));
    this.clearBtn.hidden = !list.length;
    if (!list.length) {
      this.oneshotList.appendChild(h('p', { class: 'hint' }, 'None waiting.'));
      return;
    }
    const today = parseDeviceTime(store.text(E.deviceTime));
    for (const o of list) {
      const rel = relativeDay(o.when, today);
      this.oneshotList.appendChild(h('div', { class: 'row' },
        h('span', { class: 'row-label' }, `${rel ? rel[0].toUpperCase() + rel.slice(1) : formatDate(o.when)} ${formatClock(o.when.hour, o.when.minute)}`),
        h('span', { class: 'row-value' }, `${o.portions} portion${o.portions === 1 ? '' : 's'}`)));
    }
  },

  async addOneshot() {
    const now = parseDeviceTime(store.text(E.deviceTime));
    const pe = store.get(E.oneshotPortions) || {};
    const date = h('input', { type: 'date', class: 'input', required: true, value: now ? now.date : '' });
    const time = h('input', { type: 'time', class: 'input', step: '60', required: true, value: '18:00' });
    const portions = stepper(1, parseInt(pe.min_value, 10) || 1, parseInt(pe.max_value, 10) || 6, 'Portions');
    const ok = await formDialog({
      title: 'Add a one-shot feed',
      body: [field('Date', date), field('Time', time,
               now ? `In the feeder’s time, now ${formatClock(now.hour, now.minute)} (UTC${now.offset}).` : 'In the feeder’s time.'),
             field('Portions', portions)],
      ok: 'Add',
      validate: () => (/^\d{4}-\d{2}-\d{2}$/.test(date.value) && /^\d{2}:\d{2}/.test(time.value) ? '' : 'Enter a date and a time.'),
    });
    if (!ok) return;
    const text = `${date.value} ${time.value.slice(0, 5)}`;
    const before = store.text(E.oneshots);
    this.run(async () => {
      await api.setAndConfirm(E.oneshotPortions, portions.value);
      await api.setText(E.addOneshot, text);
      const added = await api.waitForChange([E.oneshots], () => store.text(E.oneshots) !== before, 3500);
      if (!added) throw new Error('The feeder did not add it. It must be in the future (in the feeder’s time), and at most 8 can wait.');
    }, 'One-shot feed added');
  },

  async clearOneshots() {
    if (!await confirmDialog({ title: 'Clear all one-shot feeds?', body: 'Every one-shot feed still waiting is removed.',
                               ok: 'Clear all', danger: true })) return;
    this.run(() => api.press(E.clearOneshots).then(() => api.waitFor(E.oneshots, x => x.value === 'none')), 'One-shot feeds cleared');
  },
};

// ---- pages/configuration.js ----
// Configuration: the feeder's settings, each with the device's own limits and unit, saved when you press Set (or
// Enter) and confirmed by the device. The feed guard's limits are the device's: this page only changes them.

/** A settings row choosing the time zone by place (IANA name), which sets the Timezone entity to the POSIX string
 *  ESPHome would compile for it (tz_zones.js). Null without the Timezone entity. */
function timezonePicker() {
  if (!store.has(E.timezone)) return null;
  const browser = (Intl.DateTimeFormat().resolvedOptions().timeZone || '');
  const zones = tzZones();
  const sel = h('select', { class: 'input', 'aria-label': 'Time zone', onchange: () => {
    if (!sel.value) return;
    api.setAndConfirm(E.timezone, sel.value === '-' ? '' : tzPosix(sel.value))
      .then(() => toast('Time zone saved', 'ok'), err => { toastError(err); sel._update(true); });
  } },
  h('option', { value: '-' }, 'From the YAML (or Home Assistant)'),
  h('option', { value: '', hidden: true }, 'Other (a rule typed below)'),
  zones.map(([n]) => h('option', { value: n }, n.replace(/_/g, ' '))));
  sel._update = force => {
    if (!force && document.activeElement === sel) return;
    const posix = store.text(E.timezone);
    if (!posix) { sel.value = '-'; return; }
    const names = tzNamesFor(posix);
    // Several places share a rule: keep the one shown if it still fits, else prefer this browser's.
    sel.value = names.includes(sel.value) ? sel.value : names.includes(browser) ? browser : names[0] || '';
  };
  sel._update();
  const here = tzPosix(browser) ? h('button', { class: 'btn btn-small', type: 'button', onclick: () => {
    sel.value = browser;
    sel.dispatchEvent(new Event('change'));
  } }, `Use ${browser.replace(/_/g, ' ')}`) : null;
  const el = h('div', { class: 'setting' },
    h('div', { class: 'setting-text' }, h('div', { class: 'setting-label' }, 'Time zone'),
      h('div', { class: 'hint' }, 'Where the feeder is. Daylight saving and sunrise and sunset follow it.')),
    h('div', { class: 'setting-control' }, sel, here));
  el._update = () => sel._update();
  return el;
}

PAGES.configuration = {
  mount(root) {
    this.rows = [];
    const group = (title, intro, items) => {
      const rows = items.filter(Boolean);
      if (!rows.length) return null;
      this.rows.push(...rows);
      return card(title, intro ? h('p', { class: 'hint' }, intro) : null, rows);
    };

    const safety = group('Feeding safety',
      'Every feed, from the schedule, this app, Home Assistant, Bluetooth or the button, is checked against these.', [
        setting('Minimum gap between feeds', 'No feed starts sooner than this after the last one.', E.minGap),
        setting('Daily portion cap', 'Most portions in any 24 hours, scheduled ones included.', E.dailyCap),
        setting('Most portions per command', 'For feeds by hand or remote; 1 means one portion per press.', E.maxPerCommand),
        setting('Gap between portions', 'Pause between the portions of one feed.', E.portionGap),
      ]);
    const tray = group('Tray and refills', null, [
      setting('Reload pause', 'After Tray reload, scheduled feeding waits this long so you can load food. Feeds due ' +
              'in that time are skipped.', E.reloadPause),
      setting('Refill interval', 'How often you expect to refill. The schedule is flagged when it needs more than the ' +
              'tray holds before then.', E.refillInterval),
    ]);

    // Location and time
    const loc = card('Location and time',
      h('p', { class: 'hint' }, 'The location is only needed for sunrise and sunset events. Decimal degrees: north and ' +
                                 'east are positive, south and west negative. Both 0 means not set.'));
    const tz = setting('Time zone rule', 'Set by the place above, or type a POSIX TZ string, for example ' +
                       'CET-1CEST,M3.5.0,M10.5.0/3. Empty: the one in your YAML, or Home Assistant\'s.', E.timezone);
    const zone = timezonePicker();
    const ntp = setting('NTP servers', 'Up to three host names or IP addresses, separated by commas, for example ' +
                        '192.168.1.1 for a server on your network. Empty: the ones in the build (public pool servers).',
                        E.ntpServers);
    for (const r of [setting('Latitude', null, E.latitude), setting('Longitude', null, E.longitude), zone, tz, ntp]
      .filter(Boolean)) {
      this.rows.push(r);
      loc.appendChild(r);
    }
    this.timeRows = [];
    const add = (label, fn) => this.timeRows.push(boundRow(loc, label, fn));
    add('Time zone in use', () => {
      const t = parseDeviceTime(store.text(E.deviceTime));
      const from = store.text(E.timezone) ? 'set here' : 'from the YAML (or Home Assistant)';
      return t ? `UTC${t.offset}, ${from}` : from;
    });
    add('Clock', () => {
      if (store.bool(E.clockValid) === false) return 'Not set';
      const age = store.num(E.clockAge);
      return [store.text(E.timeSource), isNaN(age) ? '' : `synced ${formatDuration(age * 60) || 'just now'} ago`]
        .filter(Boolean).join(', ');
    });

    // Device
    const dev = card('Device');
    const d = (label, fn) => this.timeRows.push(boundRow(dev, label, fn));
    d('Name', () => store.title || location.hostname);
    d('Address', () => location.host);
    if (store.has(E.wifiNetwork)) d('Wi-Fi network', () => store.text(E.wifiNetwork));
    if (store.has(E.wifiSignal)) {
      d('Signal', () => {
        const s = store.num(E.wifiSignal);
        return isNaN(s) ? '' : `${s} dBm (${s >= -60 ? 'good' : s >= -70 ? 'fair' : 'weak'})`;
      });
    }
    d('Firmware', () => store.text(E.firmware));
    dev.appendChild(h('p', { class: 'hint' }, 'Diagnostics shows every address and the live log. ',
                      h('a', { href: '#setup' }, 'Run the setup wizard again'), '.'));

    this.hw = this.hardwareCard();

    // MQTT (packages/mqtt.yaml): the client and Home Assistant discovery, set up here.
    const mqtt = group('MQTT', 'Home Assistant\'s controls and status (with discovery), and the schedule on its own ' +
                       'topics (docs/MQTT.md). It reads the safety limits but cannot change them; never calibration, pins or keys. Saved at once; once it has ' +
                       'connected, changes are used after a restart.', [
      setting('MQTT', null, E.mqtt),
      setting('Broker', 'Host name or IP address.', E.mqttBroker),
      setting('Port', null, E.mqttPort),
      setting('Username', 'Empty: none.', E.mqttUsername),
      setting('Password', 'Not shown once saved. Set to change it.', E.mqttPassword),
      setting('Topic prefix', 'Empty: the device name.', E.mqttPrefix),
    ]);
    if (mqtt) {
      this.timeRows.push(boundRow(mqtt, 'Connected', () => store.bool(E.mqttConnected) ? 'Yes' : 'No'),
                         boundRow(mqtt, 'Prefix in use', () => store.text(E.mqttPrefixInUse)));
    }

    this.pw = card('Settings password');
    this.pw.hidden = true;
    this.keys = card('Keys');
    this.keys.hidden = true;
    this.net = card('Network');
    this.net.hidden = true;
    this.keyRows = [setting('Bluetooth may change the safety limits', 'Minimum gap, gap between portions, daily cap ' +
                            'and portions per command.', E.bleGuard),
                    setting('Bluetooth may change the calibration', 'Offsets, servo pulse range and calibration mode.',
                            E.bleCalibration)].filter(Boolean);
    this.rows.push(...this.keyRows);
    auth.onChange(() => {
      this.updatePassword();
      this.updateKeys();
      this.updateNetwork();
    });
    auth.refresh();
    auth.loadNetwork();

    append(root, h('div', { class: 'grid' }, safety, tray), h('div', { class: 'grid' }, loc, dev),
           h('div', { class: 'grid' }, this.hw, this.pw), h('div', { class: 'grid' }, this.keys, this.net), mqtt);
    this.update();
  },

  /** Board and pins (packages/hardware.yaml), and the disc's motor pins (mechanism_n20.yaml, D19): saved at once, used
   *  after a restart. Null with neither. */
  hardwareCard() {
    // The disc's pins, while the disc is the drive (a firmware with both drives has the selects in servo mode too).
    const motor = store.has(E.motorIn1Pin) && mechanism() !== MECHANISMS.servo;
    // A firmware carrying more than one drive (packages/drive_select.yaml) chooses it here too.
    const drives = store.has(E.drive);
    if (!store.has(E.board) && !motor && !drives) return null;
    const hw = card(drives ? 'Drive, board and pins' : store.has(E.board) ? 'Board and pins' : 'Pins',
      h('p', { class: 'hint' },
      (drives ? 'What moves the tray, and where things are wired. ' : 'Where things are wired. ') +
      'A change is saved at once and used after the next restart.'));
    // The board is the device's own select, except that "Custom" is only shown, not chosen: pick the pins instead.
    const board = h('select', { class: 'input', 'aria-label': 'Board', onchange: () => {
      if (board.value === 'Custom') {
        toast('Choose the pins one by one below');
        board._update(true);
        return;
      }
      api.setAndConfirm(E.board, board.value).catch(err => { toastError(err); board._update(true); });
    } }, ((store.has(E.board) && store.get(E.board).option) || []).map(o => h('option', { value: o }, o)));
    board._update = force => { if (force || document.activeElement !== board) board.value = store.text(E.board); };
    const boardRow = !store.has(E.board) ? null : h('div', { class: 'setting' },
      h('div', { class: 'setting-text' }, h('div', { class: 'setting-label' }, 'Board'),
        h('div', { class: 'hint' }, 'Build Default: the pins in your YAML (or the ones the firmware was built with).')),
      h('div', { class: 'setting-control' }, board));
    if (boardRow) boardRow._update = () => board._update();
    const pins = [
      drives ? setting('Drive', 'After the restart, reload the tray before feeding.', E.drive) : null,
      boardRow,
      // The servo's pin while the servo is the drive; the disc's five while the disc is (D19).
      mechanism() === MECHANISMS.servo ? setting('Servo pin', 'The servo signal wire.', E.servoPin) : null,
      ...(motor ? [setting('Motor IN1', 'DRV8833 AIN1.', E.motorIn1Pin),
                   setting('Motor IN2', 'DRV8833 AIN2.', E.motorIn2Pin),
                   setting('Motor STBY', 'DRV8833 STBY: held low keeps the motor off.', E.motorStbyPin),
                   setting('Encoder A', 'The encoder\'s C1.', E.encoderAPin),
                   setting('Encoder B', 'The encoder\'s C2.', E.encoderBPin)] : []),
      setting('Button pin', 'The optional push button; none if your build has no button.', E.buttonPin),
      setting('LED pin', 'The status LED (WS2812); none if your board has none.', E.ledPin),
    ].filter(Boolean);
    this.rows.push(...pins);
    for (const r of pins) hw.appendChild(r);
    hw.appendChild(h('p', { class: 'hint' }, 'GPIO33 to 37 are taken by the octal flash or PSRAM on some modules ' +
                     '(for example the N8R8 DevKitC-1): use them only on boards without. A servo on GPIO43 or 44 may ' +
                     'twitch at reset, when the chip prints its boot messages there.'));
    this.timeRows.push(boundRow(hw, 'In use', () => store.text(E.pinsInUse)));
    if (store.has(E.restart)) {
      const note = h('p', {}, 'A change is waiting for a restart.');
      const btn = h('button', { class: 'btn', onclick: async () => {
        if (!await confirmDialog({ title: 'Restart the feeder?', ok: 'Restart',
                                   body: 'It is back in a few seconds and carries on feeding by itself. Refused ' +
                                         'while the tray moves.' })) return;
        api.press(E.restart).then(() => toast('Restarting', 'ok'), toastError);
      } }, 'Restart');
      hw.appendChild(h('div', {}, note, h('div', { class: 'actions' }, btn)));
      this.timeRows.push(() => {
        const needed = store.bool(E.restartNeeded) === true;
        note.hidden = !needed;
        btn.classList.toggle('btn-primary', needed);
      });
    }
    return hw;
  },

  /** The password card: what is protected, and lock, unlock, set, change or remove. */
  updatePassword() {
    const pw = this.pw;
    if (!pw || !pw.isConnected) return;
    pw.hidden = !auth.available;
    while (pw.children.length > 1) pw.lastChild.remove();
    const what = 'Changing the feeding safety limits, the calibration, the pins, the keys or the network from this app';
    const btn = (label, onclick, cls = 'btn') => h('button', { class: cls, onclick }, label);
    const run = (p, ok) => p.then(() => ok && toast(ok, 'ok'), toastError);
    const forgot = h('p', { class: 'hint' }, 'Forgotten? Hold the BOOT button on the board for 10 seconds while the ' +
                     'feeder runs: that clears the password and nothing else. Home Assistant and Bluetooth do not ' +
                     'use it; they have their own keys.');
    let text, actions;
    if (!auth.set) {
      text = `No settings password. ${what} needs none: anyone who can open this page can change them.`;
      actions = [btn('Set a password', () => this.passwordDialog(false), 'btn btn-primary')];
    } else if (auth.locked()) {
      text = `${what} needs the settings password.`;
      actions = [btn('Unlock', () => this.unlockDialog(), 'btn btn-primary')];
    } else {
      text = 'Unlocked on this page until you reload it or lock it.';
      actions = [btn('Lock', () => auth.lock()), btn('Change', () => this.passwordDialog(true)),
                 btn('Remove', async () => {
                   if (!await confirmDialog({ title: 'Remove the settings password?', danger: true, ok: 'Remove',
                                              body: `${what} will need no password.` })) return;
                   run(auth.setPassword(''), 'Settings password removed');
                 }, 'btn btn-danger')];
    }
    append(pw, h('p', {}, text), h('div', { class: 'actions' }, actions), forgot);
  },

  /** The keys card: where the Home Assistant (API) and Bluetooth keys come from, and new ones. The device never sends
   *  a key, so a new key is shown once, here, and never again. */
  updateKeys() {
    const box = this.keys;
    if (!box || !box.isConnected) return;
    const k = auth.keys;
    box.hidden = !auth.available || (k.api === 'off' && k.ble === 'off' && !this.keyRows.length);
    while (box.children.length > 1) box.lastChild.remove();
    const btn = (label, onclick, cls = 'btn btn-small') => h('button', { class: cls, onclick }, label);
    const part = (title, words, actions) => h('div', { class: 'key-part' },
      h('div', { class: 'setting-label' }, title), h('p', {}, words),
      actions.length ? h('div', { class: 'actions' }, actions) : null);
    if (k.api !== 'off') {
      const words = { none: 'Not set yet. Home Assistant gives the feeder one when you adopt it, or make one here.',
                      build: 'From your YAML (api: encryption: key). Change it there.',
                      device: 'Saved on the feeder. Home Assistant uses it to connect.' }[k.api] || k.api;
      const actions = k.api === 'build' ? [] : [
        btn('Generate', () => this.newKey('api', true)), btn('Enter a key', () => this.newKey('api', false)),
        k.api === 'device' ? btn('Clear', async () => {
          if (!await confirmDialog({ title: 'Clear the Home Assistant key?', danger: true, ok: 'Clear',
                                     body: 'Home Assistant disconnects and must adopt the feeder again, which sets a ' +
                                           'new key. Until then, whoever reaches the feeder first can set one.' })) return;
          auth.setKey('api', null).then(() => toast('Home Assistant key cleared', 'ok'), toastError);
        }, 'btn btn-small btn-danger') : null].filter(Boolean);
      box.appendChild(part('Home Assistant key', words, actions));
    }
    if (k.ble !== 'off') {
      const words = { none: 'Not set: every Bluetooth client is refused until you make one.',
                      build: 'From your YAML (ble_key). A key made here replaces it.',
                      device: 'Saved on the feeder.' }[k.ble] || k.ble;
      const actions = [btn('Generate', () => this.newKey('ble', true)), btn('Enter a key', () => this.newKey('ble', false))];
      if (k.ble === 'device') {
        actions.push(btn('Clear', async () => {
          if (!await confirmDialog({ title: 'Clear the Bluetooth key?', danger: true, ok: 'Clear',
                                     body: 'Bluetooth clients disconnect and are refused until you make a new key. A ' +
                                           'feeder built from YAML with its own ble_key goes back to that one.' })) return;
          auth.setKey('ble', null).then(() => toast('Bluetooth key cleared', 'ok'), toastError);
        }, 'btn btn-small btn-danger'));
      }
      box.appendChild(part('Bluetooth key', words, actions));
    }
    for (const r of this.keyRows) box.appendChild(r);
    box.appendChild(h('p', { class: 'hint' }, 'A key is shown once, when it is made: copy it then. ' +
      (auth.set ? 'It travels to the feeder masked by the settings password.'
                : 'With no settings password it crosses your network as it is: set a password first if you do not ' +
                  'trust everyone on it.')));
  },

  /** The network card (DESIGN.md section 9.3): the name, the Wi-Fi network and the fallback access point's password.
   *  The device never sends a password. */
  updateNetwork() {
    const box = this.net, n = auth.network;
    if (!box || !box.isConnected) return;
    box.hidden = !auth.available || !n;
    while (box.children.length > 1) box.lastChild.remove();
    if (!n) return;
    const btn = (label, onclick, cls = 'btn btn-small') => h('button', { class: cls, onclick }, label);
    const run = (p, ok) => p.then(() => toast(ok, 'ok'), toastError);
    const part = (title, words, actions) => h('div', { class: 'key-part' },
      h('div', { class: 'setting-label' }, title), h('p', {}, words),
      actions.length ? h('div', { class: 'actions' }, actions) : null);

    const next = n.name_saved || n.name_build;
    const nameWords = n.name === next ? `${n.name}, ${n.name_saved ? 'set here' : 'from the build'}: the feeder ` +
                                        `answers at ${n.name}.local.`
                                      : `${n.name} until the next restart, then ${next} (${next}.local).`;
    box.appendChild(part('Name', nameWords, [
      btn('Change', () => this.nameDialog()),
      n.name_saved ? btn(`Use ${n.name_build}`, () => run(auth.setNetwork('name', { name: '' }),
                                                           'Saved: used after the next restart')) : null,
    ].filter(Boolean)));

    if (n.wifi) {
      const forget = n.forget ? btn('Forget network', async () => {
        const ap = `${n.name}-setup`;
        if (!await confirmDialog({ title: 'Forget the Wi-Fi network?', danger: true, ok: 'Forget',
                                   body: 'The feeder leaves your network and restarts, once the tray is still, with ' +
                                         `its setup access point on: join "${ap}" from a phone and the setup ` +
                                         'page opens, to pick a network. Everything else is kept: settings, ' +
                                         'calibration, keys and the tray.' })) return;
        run(auth.setNetwork('forget', {}), 'Forgetting: the feeder restarts into its setup access point');
      }, 'btn btn-small btn-danger') : null;
      box.appendChild(part('Wi-Fi network', 'Join another network. The feeder switches at once; if it cannot join, it ' +
                           'opens its access point after a minute or two so you can try again.',
                           [btn('Join a network', () => this.wifiDialog()), forget].filter(Boolean)));
    }
    if (n.ap !== 'off') {
      box.appendChild(part('Access point password', 'Used by the access point the feeder opens when it cannot join ' +
                           `Wi-Fi. ${n.ap === 'device' ? 'Set here.' : n.ap === 'open' ? 'None: anyone in range can ' +
                           'join it. Set one.' : 'From the build.'}`, [
        btn(n.ap === 'open' ? 'Set' : 'Change', () => this.apDialog(), n.ap === 'open' ? 'btn btn-small btn-primary' : undefined),
        n.ap === 'device' ? btn(n.ap_build_open ? 'Remove' : 'Use the build\'s', () => run(auth.setNetwork('ap', { password: '' }),
                                                              'Saved: used after the next restart')) : null,
      ].filter(Boolean)));
    }
    if (n.restart) {
      const restart = store.has(E.restart)
        ? btn('Restart', async () => {
          if (!await confirmDialog({ title: 'Restart the feeder?', ok: 'Restart',
                                     body: 'It is back in a few seconds and carries on feeding by itself. Refused ' +
                                           'while the tray moves.' })) return;
          api.press(E.restart).then(() => toast('Restarting', 'ok'), toastError);
        }, 'btn btn-small btn-primary') : null;
      box.appendChild(h('div', {}, h('p', {}, 'A change is waiting for a restart.'),
                        restart ? h('div', { class: 'actions' }, restart) : null));
    }
    box.appendChild(h('p', { class: 'hint' }, auth.set
      ? 'Passwords travel to the feeder masked by the settings password, and are never shown again.'
      : 'With no settings password, passwords cross your network as they are: set one first if you do not trust ' +
        'everyone on it.'));
  },

  async nameDialog() {
    const n = auth.network || {};
    const input = h('input', { class: 'input', type: 'text', autocomplete: 'off', spellcheck: 'false',
                               value: n.name_saved || n.name || '' });
    const ok = await formDialog({ title: 'Name on the network', ok: 'Save',
      body: field('Name', input, 'Lowercase letters, digits and hyphens, up to 31. Used after the next restart; Home ' +
                  'Assistant may need the feeder added again under its new name.'),
      validate: () => (/^[a-z0-9]([a-z0-9-]{0,29}[a-z0-9])?$/.test(input.value) ? ''
                       : 'Lowercase letters, digits and hyphens, not at either end, up to 31') });
    if (ok) auth.setNetwork('name', { name: input.value }).then(() => toast('Saved: used after the next restart', 'ok'),
                                                                toastError);
  },

  async wifiDialog() {
    // The networks the feeder sees (2.3.0, D31; a scan starts if it is connected), or "Other network..." typed.
    const getList = () => fetch(`${location.origin}/feeder/wifi/networks`, { cache: 'no-store' })
      .then(r => (r.ok ? r.json() : null)).then(j => (j ? parseWifiNetworks(j) : null), () => null);
    let list = await getList();
    const pick = h('select', { class: 'input', 'aria-label': 'Network' });
    const ssid = h('input', { class: 'input', type: 'text', autocomplete: 'off', spellcheck: 'false' });
    const pw = h('input', { class: 'input', type: 'password', autocomplete: 'off' });
    const status = h('span', { class: 'hint' });
    const rescan = h('button', { type: 'button', class: 'btn btn-small' }, 'Scan again');
    const typed = field('Network (SSID)', ssid);
    const pwField = field('Password', pw, 'Empty for an open network. This page loses the feeder when it switches: ' +
                          'find it again on the new network.');
    const chosen = () => (list ? list.networks.find(n => n.hex === pick.value) : null);
    const sync = () => {
      const n = chosen();
      typed.hidden = !!n;
      pwField.hidden = !!n && !n.secured;
    };
    const fill = () => {
      const keep = pick.value;
      pick.replaceChildren(...list.networks.map(n => h('option', { value: n.hex },
                             `${n.name} (${n.signal}, ${n.secured ? 'secured' : 'open'})`)),
                           h('option', { value: '' }, 'Other network...'));
      pick.value = list.networks.some(n => n.hex === keep) ? keep : list.networks.length ? list.networks[0].hex : '';
      setText(status, list.scanning ? 'Scanning...' : list.networks.length ? '' : 'None found: type the name.');
      rescan.hidden = !list.scan;
      rescan.disabled = list.scanning;
      sync();
    };
    let open = true;
    const scan = async () => {
      if (!list || !list.scan) return;
      const r = await fetch(`${location.origin}/feeder/wifi/scan`, { method: 'POST' }).catch(() => null);
      if (!r || !r.ok) return;
      list.scanning = true;
      fill();
      for (let i = 0; i < 8 && open; i++) {  // the feeder ends a scan within 10 s
        await new Promise(res => setTimeout(res, 1500));
        const next = await getList();
        if (!open || !next) return;
        list = next;
        if (!list.scanning) break;
      }
      if (open) fill();
    };
    rescan.onclick = scan;
    pick.onchange = sync;
    let body;
    if (list) {
      fill();
      body = [field('Network', pick), h('div', { class: 'actions' }, rescan, status), typed, pwField];
      scan();
    } else {
      body = [typed, pwField];
    }
    const ok = await formDialog({ title: 'Join a Wi-Fi network', ok: 'Join', body,
      validate: () => {
        if (!chosen()) {
          const n = new TextEncoder().encode(ssid.value).length;
          if (!n || n > 32) return 'The network name is 1 to 32 bytes';
        }
        const p = pw.value;
        if (!pwField.hidden && p && !(/^[\x20-\x7e]{8,63}$/.test(p) || /^[0-9a-fA-F]{64}$/.test(p)))
          return 'A Wi-Fi password is 8 to 63 characters';
        return '';
      } });
    open = false;
    if (!ok) return;
    const n = chosen();
    auth.setNetwork('wifi', n ? { ssidHex: n.hex, password: n.secured ? pw.value : '' }
                              : { ssid: ssid.value, password: pw.value })
      .then(() => toast('Joining the network: the feeder may drop off this page', 'ok'), toastError);
  },

  async apDialog() {
    const a = h('input', { class: 'input', type: 'password', autocomplete: 'new-password' });
    const b = h('input', { class: 'input', type: 'password', autocomplete: 'new-password' });
    const ok = await formDialog({ title: 'Access point password', ok: 'Save',
      body: [field('New password', a, '8 to 63 characters. Used after the next restart.'), field('Again', b)],
      validate: () => (!/^[\x20-\x7e]{8,63}$/.test(a.value) ? '8 to 63 characters (letters, digits, symbols)'
                       : a.value !== b.value ? 'The two do not match' : '') });
    if (ok) auth.setNetwork('ap', { password: a.value }).then(() => toast('Saved: used after the next restart', 'ok'),
                                                              toastError);
  },

  /** Generate (in this browser) or enter a key, save it on the feeder, and show it once. */
  async newKey(kind, generate) {
    const name = kind === 'api' ? 'Home Assistant' : 'Bluetooth';
    const who = kind === 'api' ? 'Home Assistant disconnects and needs the new key (Settings, Devices, ESPHome).'
                               : 'Bluetooth clients need the new key; a connected one must authenticate again.';
    let bytes;
    if (generate) {
      if (!await confirmDialog({ title: `Make a new ${name} key?`, ok: 'Make key', body: `It replaces the current one. ${who}` })) return;
      bytes = crypto.getRandomValues(new Uint8Array(32));
    } else {
      const input = h('input', { class: 'input', type: 'text', autocomplete: 'off', spellcheck: 'false' });
      if (!await formDialog({ title: `Enter a ${name} key`, ok: 'Save',
                              body: field('Key', input, `32 bytes in base64, as made by openssl rand -base64 32. ${who}`),
                              validate: () => (keyFromBase64(input.value) ? '' : 'Not a 32-byte base64 key') })) return;
      bytes = keyFromBase64(input.value);
    }
    try {
      await auth.setKey(kind, bytes);
    } catch (e) {
      toastError(e);
      return;
    }
    if (!generate) {
      toast(`${name} key saved`, 'ok');
      return;
    }
    const text = keyToBase64(bytes);
    const out = h('input', { class: 'input mono', type: 'text', readonly: true, value: text });
    const copy = h('button', { class: 'btn btn-small', type: 'button', onclick: () => {
      out.select();
      (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject(new Error()))
        .then(() => toast('Copied', 'ok'), () => { document.execCommand('copy'); toast('Copied', 'ok'); });
    } }, 'Copy');
    await formDialog({ title: `New ${name} key`, ok: 'Done', cancel: 'Close',
                       body: [field('Key', out, 'Saved on the feeder. This is the only time it is shown.'),
                              h('div', { class: 'actions' }, copy)] });
  },

  async unlockDialog() {
    const input = h('input', { class: 'input', type: 'password', autocomplete: 'current-password' });
    if (!await formDialog({ title: 'Unlock settings', ok: 'Unlock', body: field('Settings password', input),
                            validate: () => (input.value ? '' : 'Enter the password') })) return;
    auth.unlock(input.value).then(() => toast('Unlocked', 'ok'), toastError);
  },

  async passwordDialog(change) {
    const a = h('input', { class: 'input', type: 'password', autocomplete: 'new-password' });
    const b = h('input', { class: 'input', type: 'password', autocomplete: 'new-password' });
    const body = [field('New password', a, 'It is never sent to the feeder; this page proves it knows it. A long ' +
                        'one is best: someone recording your network could try to guess it.'),
                  field('Again', b)];
    const ok = await formDialog({ title: change ? 'Change the settings password' : 'Set a settings password', body,
      validate: () => (a.value.length < 8 ? 'At least 8 characters' : a.value !== b.value ? 'The two do not match' : '') });
    if (!ok) return;
    auth.setPassword(a.value).then(() => toast(change ? 'Password changed' : 'Password set', 'ok'), toastError);
  },

  update() {
    for (const r of this.rows) r._update();
    for (const u of this.timeRows) u();
  },
};

// ---- pages/maintenance.js ----
// Maintenance: calibrating the tray positions, the servo's pulse range, recovering the tray position, and the
// owner-approved debugging edit of the 24 h count (DESIGN.md section 13, 2026-10-14). Every step is a request the
// device carries out; feeds are refused while calibration mode is on (the device's own rule).

PAGES.maintenance = {
  mount(root) {
    this.keys = {};
    this.rows = [];
    this.busy = false;
    const parts = [];

    // The servo's slot calibration: whenever the build has its Calibration Position (packages/calibration.yaml).
    if (store.has(E.calibrationMode) && store.has(E.calibrationPosition)) {
      this.calStatus = h('p', { class: 'cal-status' });
      this.calStart = h('button', { class: 'btn btn-primary', onclick: () => this.startCalibration() }, 'Start calibration');
      this.calFinish = h('button', { class: 'btn btn-primary', onclick: finishCalibration }, 'Finish and save');
      this.slotCount = (store.get(E.calibrationPosition).option || []).length || 7;
      this.slots = h('div', { class: 'slot-picker', role: 'group', 'aria-label': 'Slot to adjust' },
        Array.from({ length: this.slotCount }, (_, i) => i).map(i => h('button', { type: 'button', class: 'btn slot-pick', 'aria-pressed': 'false',
          onclick: () => this.pickSlot(i) }, String(i))));
      this.offsetValue = h('span', { class: 'offset-value', 'aria-live': 'polite' });
      const nudge = (delta, text) => h('button', { class: 'btn', 'aria-label': `Offset ${text}`, onclick: () => this.nudge(delta) }, text);
      this.workArea = h('div', { class: 'cal-work' },
        h('div', { class: 'form-label' }, 'Slot'), this.slots,
        h('div', { class: 'form-label' }, 'Offset of this slot'),
        h('div', { class: 'nudge' }, nudge(-1, '−1°'), nudge(-0.1, '−0.1°'), this.offsetValue,
          nudge(0.1, '+0.1°'), nudge(1, '+1°')),
        h('div', { class: 'actions' },
          this.nextBtn = h('button', { class: 'btn', onclick: () => this.pickSlot(this.slot() + 1) }, 'Next slot'),
          this.calFinish));
      const pulses = [setting('Servo min pulse', 'Pulse width for 0°.', E.servoMinPulse),
                      setting('Servo max pulse', 'Pulse width for 180°. Bigger means longer steps.', E.servoMaxPulse)].filter(Boolean);
      this.rows.push(...pulses);
      parts.push(card('Calibration',
        h('p', { class: 'hint' }, 'Line each slot up with the opening in the base. Fit the tray turned fully clockwise, ' +
          'with slot 0 (the closed one) on the mark. Feeding is refused until you finish.'),
        this.calStatus,
        h('div', { class: 'actions' }, this.calStart),
        this.workArea,
        pulses.length ? h('details', { class: 'advanced' },
          h('summary', {}, 'Servo pulse range (advanced)'),
          h('p', { class: 'hint' }, 'If the error grows from slot to slot (each needs a bigger offset than the one ' +
            'before), fix that here first: Servo max pulse changes the step length, Servo min pulse lines up slot 0. ' +
            'Then fine-tune each slot. The two must stay at least 500 µs apart.'), pulses) : null));
    }

    parts.push(...mechanismCards(this.rows));

    // Recovery
    this.posRow = row('Tray', '');
    parts.push(card('Tray position',
      this.posRow.row,
      h('p', { class: 'hint' }, 'After a power cut in the middle of a feed the feeder no longer knows where the tray ' +
        'is and stops feeding. ' + mechanism().recoveryHint),
      h('div', { class: 'actions' },
        store.has(E.declarePosition) && store.has(E.declaredPosition)
          ? h('button', { class: 'btn', onclick: recoverPositionFlow }, 'Declare position') : null,
        h('button', { class: 'btn', onclick: trayReloadFlow }, 'Tray reload'))));

    // The 24 h count (owner decision 2026-10-14: debugging and recovery only)
    if (store.has(E.portions24h)) {
      this.countRow = row('Portions counted in the last 24 h', '');
      parts.push(card('Daily cap count',
        this.countRow.row,
        h('p', { class: 'hint' }, 'The number of portions the daily cap is counting right now. Changing it is for ' +
          'debugging and recovery: it never feeds or moves the tray, and every change is logged.'),
        h('div', { class: 'actions' }, h('button', { class: 'btn', onclick: () => this.editCount() }, 'Change the count'))));
    }

    append(root, ...parts);
    this.update();
  },

  slot() {
    return parseInt(store.text(E.calibrationPosition), 10) || 0;
  },

  update() {
    for (const r of this.rows) r._update();
    const state = store.text(E.trayState);
    setText(this.posRow.value, state === 'unknown' ? 'Position unknown'
      : `${mechanism().position(store.num(E.trayPosition))}, ${state}`);
    if (this.countRow) {
      const cap = store.num(E.dailyCap);
      setText(this.countRow.value, `${store.num(E.portions24h)}${isNaN(cap) ? '' : ` (cap ${cap})`}`);
    }
    if (!this.calStatus) return;
    const on = store.bool(E.calibrationMode);
    setText(this.calStatus, on ? 'Calibration mode is on: the servo follows the slot below.' : 'Calibration mode is off.');
    this.calStatus.className = on ? 'cal-status cal-on' : 'cal-status';
    this.calStart.hidden = !!on;
    this.workArea.hidden = !on;
    const slot = this.slot();
    this.slots.querySelectorAll('button').forEach((b, i) => b.setAttribute('aria-pressed', i === slot ? 'true' : 'false'));
    this.nextBtn.hidden = slot >= this.slotCount - 1;
    const off = parseFloat(store.get(E.calibrationOffset) ? store.get(E.calibrationOffset).value : NaN);
    setText(this.offsetValue, isNaN(off) ? '' : `${off > 0 ? '+' : ''}${off.toFixed(1)}°`);
  },

  async run(task, done) {
    if (this.busy) return;
    this.busy = true;
    try {
      await task();
      if (done) toast(done, 'ok');
    } catch (err) {
      toastError(err);
    } finally {
      this.busy = false;
    }
  },

  async startCalibration() {
    if (!await confirmDialog({ title: 'Start calibration?',
      body: 'The servo moves to the tray’s current slot, and every feed is refused until you finish. Scheduled ' +
            'feeds due meanwhile are skipped.', ok: 'Start' })) return;
    this.run(() => api.turnAndConfirm(E.calibrationMode, true));
  },

  pickSlot(i) {
    if (i < 0 || i >= this.slotCount) return;
    this.run(() => api.setAndConfirm(E.calibrationPosition, String(i)));
  },

  nudge(delta) {
    const e = store.get(E.calibrationOffset);
    if (!e) return;
    const lo = parseFloat(e.min_value), hi = parseFloat(e.max_value);
    const next = Math.round(Math.min(hi, Math.max(lo, parseFloat(e.value) + delta)) * 10) / 10;
    this.run(() => api.setAndConfirm(E.calibrationOffset, next));
  },

  async editCount() {
    const e = store.get(E.portions24h);
    const input = h('input', { type: 'number', class: 'input input-num', min: e.min_value, max: e.max_value, step: 1,
                               value: store.num(E.portions24h), 'aria-label': 'Portions counted' });
    const ok = await formDialog({
      title: 'Change the 24 h count',
      body: [h('p', {}, 'Lower: the oldest counted feeds are forgotten, so more feeds are allowed. Higher: an ' +
                        '"adjustment" is added to the feed history, so fewer are allowed. Nothing is fed.'),
             field('Portions counted', input)],
      ok: 'Change',
      validate: () => {
        const v = Number(input.value);
        return Number.isInteger(v) && v >= +e.min_value && v <= +e.max_value ? '' : `A whole number from ${e.min_value} to ${e.max_value}.`;
      },
    });
    if (!ok) return;
    this.run(() => api.setAndConfirm(E.portions24h, Number(input.value)), 'Count changed');
  },
};

// ---- pages/bluetooth.js ----
// Bluetooth: the BLE control plane as the device sees it. BLE Info (static facts) and BLE Session (the connection
// and counters since boot) are entities; the activity log comes from GET /feeder/ble, the last 32 connections and
// writes kept on the device. Read-only: nothing here acts on BLE, and nothing secret (key, nonce, tag) is shown,
// because the device never reports it.

const ACTIVITY_WORDS = {
  connect: ['SYS', 'Client connected'], disconnect: ['SYS', 'Client disconnected'],
  auth: ['RX', 'AUTH'], command: ['RX', null], record: ['RX', null], replay: ['RX', null],
};

PAGES.bluetooth = {
  mount(root) {
    this.updaters = [];
    this.entries = [];
    this.fetchKey = '';
    this.clearedId = 0;
    try { this.clearedId = +localStorage.getItem('pf-ble-cleared') || 0; } catch (err) { /* private mode: not kept */ }

    const status = card('Status');
    const s = (label, fn) => this.updaters.push(boundRow(status, label, fn));
    s('Bluetooth', () => 'On');
    s('Connection', () => (this.kv().connected === '1' ? 'Client connected' : 'Waiting for a client (advertising)'));
    s('Authentication', () => {
      const kv = this.kv();
      if (kv.connected !== '1') return '—';
      return kv.auth === '1' ? 'Verified' : 'Not yet';
    });
    s('Connections since start', () => this.kv().conns || '0');

    const client = card('Client');
    const c = (label, fn) => this.updaters.push(boundRow(client, label, fn));
    c('Address', () => (this.kv().peer ? `··:··:··:··:${this.kv().peer}` : '—'));
    c('Connected for', () => {
      const kv = this.kv();
      return kv.connected === '1' ? this.ago(kv.since, '') : '—';
    });
    c('Last activity', () => this.ago(this.kv().last, ' ago'));
    c('MTU', () => this.kv().mtu || '—');
    client.appendChild(h('p', { class: 'hint' }, 'Only the last two bytes of the address are kept. Phones change ' +
                                                 'their address from time to time.'));

    const proto = card('Protocol');
    this.facts = h('div', { class: 'metrics' });
    proto.appendChild(this.facts);
    const p = (label, fn) => this.updaters.push(boundRow(proto, label, fn));
    p('Service', () => this.info().service || '');
    p('Time from Bluetooth', () => ({ fallback_only: 'Only when network time is stale', always: 'Always accepted',
                                      off: 'Refused' }[this.info().time] || this.info().time || ''));
    p('Key', () => ({ none: 'None set: every client is refused', build: 'From the YAML',
                      device: 'Saved on the feeder' }[this.info().key] || '—'));
    p('Clients may change', () => {
      const i = this.info();
      if (i.guard === undefined) return '—';
      const may = [i.guard === '1' ? 'safety limits' : '', i.calibration === '1' ? 'calibration' : ''].filter(Boolean);
      return `Feeding and the schedule${may.length ? ', ' + may.join(' and ') : ''} (Configuration, Keys)`;
    });

    this.activityBox = h('div', { class: 'activity', role: 'log' });
    const activity = card('Activity',
      h('div', { class: 'toolbar' },
        h('button', { class: 'btn btn-small', onclick: () => this.clearView() }, 'Clear view'),
        h('button', { class: 'btn btn-small', onclick: () => this.loadActivity(true) }, 'Refresh')),
      this.activityBox,
      h('p', { class: 'hint' }, 'The last 32 connections and writes, kept by the feeder until it restarts. Reads ' +
        'and status notifications are only counted. Clear view only hides lines in this browser.'));

    append(root, h('div', { class: 'grid' }, status, client), proto, activity);
    this.timer = setInterval(() => this.update(), 1000);
    this.update();
  },

  unmount() {
    clearInterval(this.timer);
  },

  kv() {
    return parseKV(store.text(E.bleSession));
  },
  info() {
    return parseKV(store.text(E.bleInfo));
  },

  /** A device uptime (seconds) as time before now: "3 min ago". */
  ago(uptimeText, suffix) {
    const t = parseInt(uptimeText, 10), now = store.uptime();
    if (isNaN(t) || t < 0 || now === null) return '—';
    const d = Math.max(0, now - t);
    return d < 2 && suffix ? 'just now' : `${formatDuration(d)}${suffix}`;
  },

  update() {
    for (const u of this.updaters) u();
    const kv = this.kv(), info = this.info();
    const metrics = [
      ['Protocol', info.protocol ? `version ${info.protocol}` : '—'],
      ['Authentication', (info.auth || '').toUpperCase() || '—'],
      ['Writes in', kv.wr || '0', kv.wrb ? `${kv.wrb} bytes` : ''],
      ['Reads', kv.rd || '0', kv.rdb ? `${kv.rdb} bytes` : ''],
      ['Notifications out', kv.nt || '0', kv.ntb ? `${kv.ntb} bytes` : ''],
      ['AUTH accepted', kv.authok || '0'],
      ['AUTH refused', kv.authfail || '0', '', +kv.authfail > 0],
      ['Refused writes', kv.refused || '0', 'not authorized', +kv.refused > 0],
      ['Invalid writes', kv.invalid || '0', '', +kv.invalid > 0],
    ];
    if (this.changed !== JSON.stringify(metrics)) {
      this.changed = JSON.stringify(metrics);
      clear(this.facts);
      for (const [label, value, sub, warn] of metrics) {
        this.facts.appendChild(h('div', { class: warn ? 'metric metric-warn' : 'metric' },
          h('div', { class: 'metric-label' }, label), h('div', { class: 'metric-value' }, value),
          sub ? h('div', { class: 'metric-sub' }, sub) : null));
      }
    }
    // The log only changes with a connection or a write, so fetch it again only then.
    const key = `${kv.conns}|${kv.wr}|${kv.connected}`;
    if (key !== this.fetchKey) {
      this.fetchKey = key;
      this.loadActivity(false);
    }
  },

  async loadActivity(byHand) {
    try {
      const r = await fetch(`${location.origin}/feeder/ble`);
      if (!r.ok) throw new Error(`the feeder answered ${r.status}`);
      this.entries = (await r.json()).entries || [];
      this.renderActivity();
      if (byHand) toast('Activity refreshed', 'ok');
    } catch (err) {
      clear(this.activityBox);
      this.activityBox.appendChild(h('p', { class: 'hint' }, `The activity log could not be read (${err.message}).`));
    }
  },

  renderActivity() {
    clear(this.activityBox);
    // Ids start again at 1 when the feeder restarts: a remembered "cleared up to" beyond the newest is stale.
    const newest = this.entries.length ? this.entries[this.entries.length - 1].id : 0;
    if (newest < this.clearedId) {
      this.clearedId = 0;
      try { localStorage.removeItem('pf-ble-cleared'); } catch (err) { /* not kept */ }
    }
    const shown = this.entries.filter(e => e.id > this.clearedId);
    if (!shown.length) {
      this.activityBox.appendChild(h('p', { class: 'hint' }, 'Nothing yet.'));
      return;
    }
    const now = store.uptime();
    for (const e of shown.slice().reverse()) {  // newest first
      const [dir, fixed] = ACTIVITY_WORDS[e.kind] || ['?', e.kind];
      const at = now === null ? null : new Date(Date.now() - Math.max(0, now - e.t) * 1000);
      const what = fixed || e.name || '';
      const ok = e.result === 'ok';
      this.activityBox.appendChild(h('div', { class: 'act' },
        h('span', { class: 'act-time' }, at ? at.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : ''),
        h('span', { class: `act-dir act-${dir.toLowerCase()}` }, dir),
        h('span', { class: 'act-what' }, what, e.kind === 'replay' ? h('span', { class: 'tag' }, 'retry') : null,
          e.seq !== undefined ? h('span', { class: 'act-seq' }, `seq ${e.seq}`) : null),
        e.result !== undefined
          ? h('span', { class: ok ? 'pill pill-ok' : 'pill pill-warn' }, ok ? 'ok' : e.result + (e.detail ? ` (${e.detail})` : ''))
          : h('span', {})));
    }
  },

  clearView() {
    this.clearedId = this.entries.length ? this.entries[this.entries.length - 1].id : this.clearedId;
    try { localStorage.setItem('pf-ble-cleared', String(this.clearedId)); } catch (err) { /* not kept */ }
    this.renderActivity();
  },
};

// ---- pages/diagnostics.js ----
// Diagnostics: always present. System and clock, network and memory (when those packages are built in), the live
// log, and every entity the device reports with a control for each: the debug view, and the fallback for anything
// no other page shows.

const DOMAIN_TITLES = {
  sensor: 'Sensors', binary_sensor: 'Binary sensors', text_sensor: 'Text sensors', button: 'Buttons',
  switch: 'Switches', select: 'Selects', number: 'Numbers', text: 'Text inputs',
};
const LEVELS = { E: 0, W: 1, I: 2, C: 2, D: 3, V: 4 };

PAGES.diagnostics = {
  mount(root) {
    this.updaters = [];
    this.timer = setInterval(() => this.updateSystem(), 1000);

    // System
    const sys = card('System');
    const add = (label, fn) => this.updaters.push(boundRow(sys, label, fn));
    add('Firmware', () => store.text(E.firmware) || 'unknown');
    add('Device name', () => store.title || location.hostname);
    add('Running for', () => formatDuration(store.uptime()));
    if (store.has(E.deviceTime)) {
      add('Device time', () => {
        const t = parseDeviceTime(store.text(E.deviceTime));
        return t ? `${formatDate(t)} ${formatClock(t.hour, t.minute)} (UTC${t.offset})` : store.text(E.deviceTime);
      });
    }
    add('Clock', () => {
      if (store.bool(E.clockValid) === false) return 'not set';
      const age = store.num(E.clockAge);
      return [store.text(E.timeSource), isNaN(age) ? '' : `synced ${formatDuration(age * 60) || 'just now'} ago`]
        .filter(Boolean).join(', ');
    });
    this.sysUpdaters = this.updaters.slice();
    if (store.has(E.firmware)) {
      sys.appendChild(h('div', { class: 'actions' }, h('a', { class: 'btn', href: '#firmware' }, 'Updates and firmware upload')));
    }

    // Network (network_info package)
    const net = store.has(E.wifiNetwork) || store.has(E.ipAddress1) ? card('Network') : null;
    if (net) {
      const n = (label, fn) => this.updaters.push(boundRow(net, label, fn));
      n('Wi-Fi network', () => store.text(E.wifiNetwork));
      // One row per address the feeder has (IPv4 and, with IPv6 on, link-local and global ones).
      for (const id of [E.ipAddress1, E.ipAddress2, E.ipAddress3, E.ipAddress4]) {
        if (!store.has(id)) continue;
        const r = row('', '');
        r.row.classList.add('address-row');
        net.appendChild(r.row);
        this.updaters.push(() => {
          const a = store.text(id), kind = addressKind(a);
          r.row.hidden = !kind;
          setText(r.row.firstChild, kind);
          setText(r.value, a);
        });
      }
      if (store.has(E.wifiSignal)) {
        n('Signal', () => {
          const s = store.num(E.wifiSignal);
          if (isNaN(s)) return '';
          return `${s} dBm (${s >= -60 ? 'good' : s >= -70 ? 'fair' : 'weak'})`;
        });
      }
    }

    // Memory (diagnostics package)
    const mem = store.has(E.freeHeap) ? card('Memory') : null;
    if (mem) {
      const kb = id => () => isNaN(store.num(id)) ? '' : `${Math.round(store.num(id) / 1024)} KB`;
      const m = (label, fn) => this.updaters.push(boundRow(mem, label, fn));
      m('Free heap', kb(E.freeHeap));
      m('Largest free block', kb(E.largestBlock));
      m('Fragmentation', () => isNaN(store.num(E.fragmentation)) ? '' : `${Math.round(store.num(E.fragmentation))} %`);
      m('Longest loop', () => isNaN(store.num(E.loopTime)) ? '' : `${Math.round(store.num(E.loopTime))} ms`);
    }

    // Log
    this.paused = false;
    this.minLevel = 2;
    this.shownCount = Math.max(0, store.logCount - store.logLines.length);
    this.logBox = h('div', { class: 'log', role: 'log', 'aria-live': 'off', tabindex: '0' });
    const level = h('select', { class: 'input input-small', 'aria-label': 'Log level', onchange: () => {
      this.minLevel = +level.value;
      this.redrawLog();
    } }, h('option', { value: '4' }, 'Everything'), h('option', { value: '2', selected: true }, 'Info and above'),
         h('option', { value: '1' }, 'Warnings and errors'));
    const pause = h('button', { class: 'btn btn-small', onclick: () => {
      this.paused = !this.paused;
      setText(pause, this.paused ? 'Resume' : 'Pause');
      if (!this.paused) this.redrawLog();
    } }, 'Pause');
    const log = card('Log',
      h('div', { class: 'toolbar' }, level, pause,
        h('button', { class: 'btn btn-small', onclick: () => { this.clearedAt = store.logCount; this.redrawLog(); } }, 'Clear'),
        h('button', { class: 'btn btn-small', onclick: () => this.copyLog() }, icon('copy', 16), 'Copy')),
      this.logBox,
      h('p', { class: 'hint' }, 'Lines appear from when this page connected. The logger level in your YAML decides ' +
                                 'what the feeder sends (INFO by default).'));
    this.clearedAt = 0;

    // All entities
    this.filter = '';
    this.entityBox = h('div', { class: 'entities' });
    const search = h('input', { class: 'input', type: 'search', placeholder: 'Filter by name', 'aria-label': 'Filter entities',
                                oninput: () => { this.filter = search.value.trim().toLowerCase(); this.buildEntities(); } });
    const all = card('All entities', h('p', { class: 'hint' },
      'Everything this feeder reports, with a control for each. Changes act on the feeder straight away, ' +
      'through the same checks as everywhere else.'), search, this.entityBox);

    append(root, h('div', { class: 'grid' }, sys, net, mem), log, all);
    this.entityCount = -1;
    this.redrawLog();
    this.update(new Set(['*all']));
  },

  updateSystem() {
    for (const u of this.sysUpdaters) u();
  },

  update(changed) {
    for (const u of this.updaters) u();
    if (changed.has('*log') && !this.paused) this.appendLog();
    if (store.entities.size !== this.entityCount) this.buildEntities();
    else for (const id of changed) this.updateEntity(id);
  },

  unmount() {
    clearInterval(this.timer);
  },

  // ---- log ----
  logLine(entry) {
    const p = parseLogLine(entry.text);
    if ((LEVELS[p.level] ?? 2) > this.minLevel) return null;
    const time = new Date(entry.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return h('div', { class: `log-line log-${p.level || 'I'}` },
      h('span', { class: 'log-time' }, time), h('span', { class: 'log-level' }, p.level || '·'),
      p.tag ? h('span', { class: 'log-tag' }, p.tag) : null, h('span', { class: 'log-text' }, p.text));
  },
  visibleLines() {
    const first = store.logCount - store.logLines.length;  // count of the oldest line kept
    return store.logLines.filter((_, i) => first + i >= this.clearedAt);
  },
  redrawLog() {
    clear(this.logBox);
    const lines = this.visibleLines().map(l => this.logLine(l)).filter(Boolean);
    if (!lines.length) this.logBox.appendChild(h('p', { class: 'log-empty' }, 'No log lines yet.'));
    append(this.logBox, lines);
    this.shownCount = store.logCount;
    this.logBox.scrollTop = this.logBox.scrollHeight;
  },
  appendLog() {
    const atBottom = this.logBox.scrollHeight - this.logBox.scrollTop - this.logBox.clientHeight < 30;
    const first = store.logCount - store.logLines.length;
    const fresh = store.logLines.filter((_, i) => first + i >= Math.max(this.shownCount, this.clearedAt));
    this.shownCount = store.logCount;
    const empty = this.logBox.querySelector('.log-empty');
    for (const l of fresh) {
      const el = this.logLine(l);
      if (!el) continue;
      if (empty) empty.remove();
      this.logBox.appendChild(el);
    }
    while (this.logBox.childElementCount > 300) this.logBox.firstElementChild.remove();
    if (atBottom) this.logBox.scrollTop = this.logBox.scrollHeight;
  },
  copyLog() {
    const text = this.visibleLines().map(l => {
      const p = parseLogLine(l.text);
      return `${new Date(l.at).toLocaleTimeString()} [${p.level}][${p.tag}] ${p.text}`;
    }).join('\n');
    const done = () => toast('Log copied', 'ok');
    // The Clipboard API needs HTTPS; the feeder serves plain HTTP, so fall back to a hidden text box.
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, toastError);
      return;
    }
    const area = h('textarea', { class: 'offscreen' });
    area.value = text;
    document.body.appendChild(area);
    area.select();
    try {
      document.execCommand('copy');
      done();
    } catch (err) {
      toast('Could not copy: select the log text instead', 'error');
    }
    area.remove();
  },

  // ---- all entities ----
  buildEntities() {
    this.entityCount = store.entities.size;
    this.rows = new Map();
    clear(this.entityBox);
    const groups = new Map();
    for (const [id, e] of store.entities) {
      const name = e.name || id;
      if (this.filter && !name.toLowerCase().includes(this.filter)) continue;
      const domain = e.domain || id.slice(0, id.indexOf('/'));
      if (!groups.has(domain)) groups.set(domain, []);
      groups.get(domain).push([id, e]);
    }
    for (const domain of Object.keys(DOMAIN_TITLES).concat([...groups.keys()].filter(d => !DOMAIN_TITLES[d]))) {
      const items = groups.get(domain);
      if (!items) continue;
      items.sort((a, b) => (a[1].name || a[0]).localeCompare(b[1].name || b[0]));
      const list = h('div', { class: 'entity-list' });
      for (const [id, e] of items) {
        const value = h('span', { class: 'entity-state' });
        const control = entityControl(id);
        const tags = [e.entity_category === 1 ? 'config' : null, e.entity_category === 2 ? 'diagnostic' : null,
                      e.is_disabled_by_default ? 'hidden in Home Assistant' : null].filter(Boolean);
        list.appendChild(h('div', { class: 'entity-row' },
          h('div', { class: 'entity-name' }, e.name || id, tags.length ? h('span', { class: 'tags' }, tags.join(' · ')) : null),
          domain === 'button' || domain === 'switch' ? null : value,
          control));
        this.rows.set(id, { value, control });
        this.updateEntity(id);
      }
      this.entityBox.appendChild(h('details', { class: 'entity-group', open: true },
        h('summary', {}, `${DOMAIN_TITLES[domain] || domain} (${items.length})`), list));
    }
    if (!groups.size) this.entityBox.appendChild(h('p', { class: 'hint' }, this.filter ? 'Nothing matches.' : 'Waiting for the feeder…'));
  },
  updateEntity(id) {
    const r = this.rows && this.rows.get(id);
    if (!r) return;
    const e = store.get(id);
    setText(r.value, e.state === undefined ? '' : e.state);
    if (r.control && r.control._update) r.control._update();
  },
};

// ---- pages/setup.js ----
// Setup: the first-run wizard (2.0.0 N6, DESIGN.md section 9.4). Not a tab: the app opens #setup by itself while the
// feeder reports that setup is not finished (GET /feeder/network), and Configuration links to it. Every step uses the
// same controls as Configuration and saves as it goes; nothing waits for the last step, and every step can be skipped.

PAGES.setup = {
  STEPS: ['Welcome', 'Network', 'Time and place', 'Board and pins', 'Keys', 'Settings password', 'Calibration'],

  mount(root) {
    this.root = root;
    this.step = 0;
    this.rows = [];
    this.timeRows = [];
    this.offAuth = () => this.refreshAuth();
    auth.onChange(this.offAuth);
    auth.loadNetwork();
    this.render();
  },

  unmount() {
    this.root = null;
    const i = auth._listeners.indexOf(this.offAuth);
    if (i >= 0) auth._listeners.splice(i, 1);
  },

  /** Steps this build has: no board step without the hardware package, no keys step with no key to manage. */
  shown(i) {
    const name = this.STEPS[i];
    if (name === 'Board and pins') return store.has(E.board);
    if (name === 'Keys') return auth.keys.api !== 'off' || auth.keys.ble !== 'off';
    if (name === 'Calibration') return store.has(E.calibrationMode);
    return true;
  },
  move(dir) {
    let i = this.step + dir;
    while (i > 0 && i < this.STEPS.length - 1 && !this.shown(i)) i += dir;
    this.step = Math.max(0, Math.min(this.STEPS.length - 1, i));
    this.render();
    window.scrollTo(0, 0);
  },

  async finish(where) {
    try {
      await auth.setSetupDone(true);
    } catch (e) {
      toastError(e);
      return;
    }
    toast('Setup finished. Everything here is in Configuration too.', 'ok');
    location.hash = where;
  },

  render() {
    if (!this.root) return;
    clear(this.root);
    this.rows = [];
    this.timeRows = [];
    this.after = null;
    const visible = this.STEPS.map((_, i) => i).filter(i => this.shown(i));
    const at = visible.indexOf(this.step) + 1;
    const head = h('div', { class: 'wizard-head' },
      h('div', { class: 'wizard-count' }, `Step ${at} of ${visible.length}`),
      h('div', { class: 'wizard-bar', role: 'progressbar', 'aria-valuemin': 1, 'aria-valuemax': visible.length,
                 'aria-valuenow': at, style: `--done: ${(at / visible.length) * 100}%` }));
    const body = this[`step${this.step}`]();
    const first = this.step === 0, last = this.step === this.STEPS.length - 1;
    const nav = h('div', { class: 'actions wizard-nav' },
      first ? null : h('button', { class: 'btn', onclick: () => this.move(-1) }, 'Back'),
      h('span', { class: 'spacer' }),
      last ? null : h('button', { class: 'btn btn-primary', onclick: () => this.move(1) }, first ? 'Start' : 'Next'));
    append(this.root, head, card(this.STEPS[this.step], body, nav),
           first || last ? null : h('p', { class: 'hint wizard-skip' }, 'Nothing here is required. ',
             h('a', { href: '#', onclick: ev => { ev.preventDefault(); this.finish('#dashboard'); } },
               'Skip the rest of setup'), '.'));
    if (this.after) this.after();  // parts that fill themselves once they are on the page
    this.update();
  },

  step0() {
    return [
      h('p', {}, 'A few steps to get the feeder ready: its name and network, where it is, how it is wired, the keys ' +
                 'for Home Assistant and Bluetooth, a settings password, and lining up the tray.'),
      h('p', {}, 'Each step saves as you go and can be skipped. All of it is in Configuration and Maintenance later.'),
      h('p', { class: 'hint' }, h('a', { href: '#', onclick: ev => { ev.preventDefault(); this.finish('#dashboard'); } },
        'Skip setup'), ': the feeder already works with what it was built with.'),
    ];
  },

  step1() {
    const n = auth.network;
    if (!n) return h('p', {}, 'The feeder did not report its network settings. You can set them later in Configuration.');
    const cfg = PAGES.configuration;
    const btn = (label, onclick, primary) => h('button', { class: primary ? 'btn btn-small btn-primary' : 'btn btn-small', onclick }, label);
    const out = [
      h('div', { class: 'key-part' }, h('div', { class: 'setting-label' }, 'Name'),
        h('p', {}, `${n.name_saved || n.name}: the feeder answers at ${n.name_saved || n.name}.local` +
                   `${n.name_saved && n.name_saved !== n.name ? ' after a restart' : ''}. Give each feeder its own name.`),
        h('div', { class: 'actions' }, btn('Change the name', () => cfg.nameDialog()))),
    ];
    if (n.wifi) {
      out.push(h('div', { class: 'key-part' }, h('div', { class: 'setting-label' }, 'Wi-Fi'),
        h('p', {}, store.text(E.wifiNetwork) ? `Connected to ${store.text(E.wifiNetwork)}. ` : '',
          'To move it to another network, join it here: the feeder switches at once and this page loses it.'),
        h('div', { class: 'actions' }, btn('Join another network', () => cfg.wifiDialog()))));
    }
    if (n.ap !== 'off') {
      out.push(h('div', { class: 'key-part' }, h('div', { class: 'setting-label' }, 'Access point password'),
        h('p', {}, 'When the feeder cannot join Wi-Fi it opens its own access point. ' +
                   (n.ap === 'device' ? 'Its password is set here.'
                    : n.ap === 'open' ? 'It has no password, so anyone in range could join it and change this ' +
                                        'feeder\'s settings. Setting one is strongly recommended.'
                                      : 'It still has the password it was built with: change it.')),
        n.ap === 'open' ? h('p', { role: 'note' }, h('span', { class: 'pill pill-warn' }, 'Strongly recommended')) : null,
        h('div', { class: 'actions' }, btn(n.ap === 'open' ? 'Set a password' : 'Change the password', () => cfg.apDialog(), n.ap !== 'device'))));
    }
    return out;
  },

  step2() {
    const box = h('div', {});
    const rows = [timezonePicker(), setting('Latitude', null, E.latitude), setting('Longitude', null, E.longitude),
                  setting('NTP servers', 'Optional: a time server on your network (for example 192.168.1.1), or up to ' +
                          'three separated by commas. Empty: public pool servers.', E.ntpServers)]
      .filter(Boolean);
    this.rows.push(...rows);
    append(box, h('p', {}, 'The time zone decides when "08:00" is, and when daylight saving changes. Latitude and ' +
                           'longitude are only needed for sunrise and sunset events: decimal degrees, north and east ' +
                           'positive (a map app shows them for a place).'), rows);
    this.timeRows.push(boundRow(box, 'Feeder time', () => {
      const t = parseDeviceTime(store.text(E.deviceTime));
      return t ? `${formatClock(t.hour, t.minute)} (UTC${t.offset})` : 'Not set yet';
    }));
    return box;
  },

  step3() {
    // Configuration's own card, kept up to date from here.
    const hw = PAGES.configuration.hardwareCard.call(this);
    if (!hw) return h('p', {}, 'This build has fixed pins.');
    const parts = [...hw.children].slice(1);  // without the card's own title
    return [h('p', {}, 'Which board this is, and where the servo, the button and the LED are wired. The pins are ' +
                       'used after a restart.'), parts];
  },

  step4() {
    // Configuration's keys card fills everything after its first child (its title there; a placeholder here).
    const box = h('div', {}, h('span', { hidden: true }));
    this.keys = box;
    this.keyRows = [setting('Bluetooth may change the safety limits', null, E.bleGuard),
                    setting('Bluetooth may change the calibration', null, E.bleCalibration)].filter(Boolean);
    this.rows.push(...this.keyRows);
    this.newKey = PAGES.configuration.newKey;
    this.after = () => PAGES.configuration.updateKeys.call(this);
    return [h('p', {}, 'Home Assistant and Bluetooth clients prove themselves with keys. Home Assistant sets its own ' +
                       'when you add the feeder (Settings, Devices and services). A Bluetooth client needs one made ' +
                       'here.'), box];
  },

  step5() {
    const box = h('div', {}, h('span', { hidden: true }));
    this.pw = box;
    this.passwordDialog = PAGES.configuration.passwordDialog;
    this.unlockDialog = PAGES.configuration.unlockDialog;
    this.after = () => PAGES.configuration.updatePassword.call(this);
    return [h('p', {}, 'Optional. With a password, changing the safety limits, the calibration, the pins, the keys ' +
                       'or the network from this app needs it. Feeding and the schedule never do.'), box];
  },

  step6() {
    const restart = store.bool(E.restartNeeded) === true || (auth.network && auth.network.restart);
    return [
      h('p', {}, 'Last, line the tray up with the opening: Maintenance has a walkthrough (set the servo range, ' +
                 'then nudge each slot). Then load food with Tray reload and set a schedule.'),
      restart ? h('p', {}, 'A change from setup is waiting for a restart; Configuration has the Restart button.') : null,
      h('div', { class: 'actions' },
        h('button', { class: 'btn btn-primary', onclick: () => this.finish('#maintenance') }, 'Finish and calibrate'),
        h('button', { class: 'btn', onclick: () => this.finish('#dashboard') }, 'Finish')),
    ];
  },

  refreshAuth() {
    if (!this.root) return;
    const name = this.STEPS[this.step];
    if (name === 'Network') this.render();
    else if (name === 'Keys') PAGES.configuration.updateKeys.call(this);
    else if (name === 'Settings password') PAGES.configuration.updatePassword.call(this);
  },

  update() {
    for (const r of this.rows) r._update();
    for (const u of this.timeRows) u();
  },
};

// ---- pages/firmware.js ----
// Firmware (2.0.0 N7, DESIGN.md section 9.5): the update check and the upload. Not a tab: #firmware, linked from
// Diagnostics. The check is the browser's, not the feeder's: it reads the release manifest from GitHub Pages when this
// page opens (unless turned off here), so a feeder with no internet access loses nothing. The upload is signed with
// the settings password, over the image's SHA-256, which the feeder checks again before it switches.

const MANIFEST_URL = 'https://jspeer.github.io/precision-feeder/manifest.json';
const RELEASES_URL = 'https://github.com/jspeer/precision-feeder/releases';
const CHECK_PREF = 'pf.updateCheck';  // 'off' turns the check off in this browser
// A network that drops packets silently would leave the check "Checking…" for minutes: give up after this long.
const CHECK_TIMEOUT_MS = 10000;

function updateCheckOn() {
  try { return localStorage.getItem(CHECK_PREF) !== 'off'; } catch (e) { return true; }
}

PAGES.firmware = {
  mount(root) {
    this.manifest = null;
    this.checkEl = h('div', { 'aria-live': 'polite' });
    const toggle = h('input', { type: 'checkbox', checked: updateCheckOn(), onchange: () => {
      try { localStorage.setItem(CHECK_PREF, toggle.checked ? 'on' : 'off'); } catch (e) { /* not kept */ }
      this.check();
    } });
    this.installed = row('Installed', '');
    this.fileEl = h('input', { type: 'file', accept: '.bin', onchange: () => this.choose() });
    this.fileInfo = h('p', { class: 'hint', 'aria-live': 'polite' });
    this.uploadBtn = h('button', { class: 'btn btn-primary', disabled: true, onclick: () => this.upload() }, 'Upload and restart');
    this.progress = h('progress', { max: 1, value: 0, hidden: true });
    append(root,
      card('Updates', this.installed.row, this.checkEl,
        h('label', { class: 'check' }, toggle, ' Check for updates when this page opens (this browser only)')),
      card('Upload firmware',
        h('p', { class: 'hint' }, 'Choose the .ota.bin for this feeder\'s variant. The feeder checks it, then ' +
          'restarts into it. Settings and calibration are kept.'),
        this.fileEl, this.fileInfo, this.progress, h('div', { class: 'actions' }, this.uploadBtn)));
    this.update();
    this.check();
  },

  update() {
    const variant = store.text(E.firmwareVariant);
    setText(this.installed.value, [store.text(E.firmware) || 'unknown', variant].filter(Boolean).join(', '));
  },

  async check() {
    const link = text => h('a', { href: RELEASES_URL, target: '_blank', rel: 'noopener' }, text);
    if (!updateCheckOn()) {
      this.show(h('p', { class: 'hint' }, 'The update check is off. ', link('Releases')));
      return;
    }
    this.show(h('p', { class: 'hint' }, 'Checking…'));
    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), CHECK_TIMEOUT_MS);
    try {
      const r = await fetch(MANIFEST_URL, { cache: 'no-store', signal: abort.signal });
      this.manifest = r.ok ? await r.json() : null;
    } catch (e) {
      this.manifest = null;
    }
    clearTimeout(timer);
    const u = updateState(this.manifest, store.text(E.firmware), store.text(E.firmwareVariant));
    const notes = this.manifest && this.manifest.notes;
    if (!this.manifest) this.show(h('p', {}, 'Couldn\'t check for updates. ', link('Releases')));
    else if (u.state === 'update') {
      this.show(h('p', {}, h('strong', {}, `Version ${u.latest} is available. `),
        notes ? h('a', { href: notes, target: '_blank', rel: 'noopener' }, 'Release notes') : link('Releases')));
    } else if (u.state === 'current') this.show(h('p', {}, `Up to date (latest release ${u.latest}).`));
    else if (u.state === 'yaml') {
      this.show(h('p', {}, `Latest release ${u.latest}. Built from your own YAML: update with ESPHome.`));
    } else if (u.state === 'unlisted') {
      this.show(h('p', {}, `No published updates for this variant (${store.text(E.firmwareVariant)}): it is built ` +
        `from its own branch. Latest release of the main firmware: ${u.latest}.`));
    } else this.show(h('p', {}, `Latest release ${u.latest}. `, link('Releases')));
    if (this.bytes) this.choose();  // name the chosen file now that the manifest is known
  },

  show(node) { clear(this.checkEl); this.checkEl.appendChild(node); },

  async choose() {
    const file = this.fileEl.files[0];
    this.bytes = null;
    this.uploadBtn.disabled = true;
    if (!file) { setText(this.fileInfo, ''); return; }
    setText(this.fileInfo, 'Checking the file…');
    const bytes = new Uint8Array(await file.arrayBuffer());
    // An app image: the image magic, and the app description's magic at byte 32 (a .factory.bin starts with the
    // bootloader instead). The feeder checks the same.
    if (bytes[0] !== 0xe9 || bytes[32] !== 0x32 || bytes[33] !== 0x54 || bytes[34] !== 0xcd || bytes[35] !== 0xab) {
      setText(this.fileInfo, bytes[0] === 0xe9 ? 'That is a first-flash image (.factory.bin): choose the .ota.bin.'
                                               : 'That is not an ESP32 firmware image.');
      return;
    }
    this.bytes = bytes;
    this.sha = toHex(sha256(bytes));
    this.image = identifyImage(this.manifest, this.sha);
    const variant = store.text(E.firmwareVariant);
    let text;
    if (!this.image) {
      text = 'Not a released image: upload it only if you built it yourself.';
    } else {
      text = `Release ${this.image.version}, ${this.image.variant}: checked against the release.` +
        (variant && variant !== 'yaml' && this.image.variant !== variant ? ` This feeder runs ${variant}.` : '');
    }
    setText(this.fileInfo, text);
    this.uploadBtn.disabled = !this.bytes;
  },

  async upload() {
    const variant = store.text(E.firmwareVariant);
    const warn = !this.image ? 'Not a released image. A wrong one can stop the feeder starting (recover over USB).'
      : this.image.variant !== variant ? `This feeder runs ${variant || 'another build'}; this image is ` +
                                         `${this.image.variant}.` : '';
    const ok = await confirmDialog({ title: 'Upload firmware?', danger: !!warn, ok: 'Upload',
      body: `${warn ? warn + ' ' : ''}The feeder restarts into it when the upload ends.` });
    if (!ok) return;
    this.uploadBtn.disabled = true;
    this.progress.hidden = false;
    try {
      await auth.uploadFirmware(this.bytes, this.sha, p => { this.progress.value = p; });
      toast('Uploaded. The feeder is restarting…', 'ok', 8000);
      setText(this.fileInfo, 'Uploaded: the feeder restarts into it and this page reconnects.');
    } catch (e) {
      toastError(e);
      this.uploadBtn.disabled = false;
    }
    this.progress.hidden = true;
  },
};

// ---- app.js ----
// The shell: header, banner, tabs and routing, then start the connection. Tabs appear only for what this build
// contains (the entities each needs) and only once its page exists; nothing is configured in the app itself.

const TABS = [
  { id: 'dashboard', title: 'Dashboard', short: 'Home', icon: 'grid', shown: () => store.has(E.trayState) },
  { id: 'schedule', title: 'Schedule', short: 'Schedule', icon: 'calendar', shown: () => store.has(E.editProfile) },
  { id: 'configuration', title: 'Configuration', short: 'Config', icon: 'sliders', shown: () => store.has(E.dailyCap) },
  { id: 'maintenance', title: 'Maintenance', short: 'Service', icon: 'tool',
    shown: () => store.has(E.calibrationMode) || store.has(E.declarePosition) || store.has(E.portions24h) },
  { id: 'bluetooth', title: 'Bluetooth', short: 'BLE', icon: 'bluetooth', shown: () => store.has(E.bleSession) },
  { id: 'diagnostics', title: 'Diagnostics', short: 'Diag', icon: 'activity', shown: () => true },
  // Not in the tab bar: opened by itself on a feeder that is not set up yet, and from Configuration.
  { id: 'setup', title: 'Setup', hidden: true, shown: () => store.has(E.dailyCap) },
  // Not in the tab bar either: linked from Diagnostics (2.0.0 N7).
  { id: 'firmware', title: 'Firmware', hidden: true, shown: () => store.has(E.firmware) },
];
// The initial list of entities arrives in a burst; it has settled once nothing new has come for this long.
const SETTLE_MS = 700;

const app = {
  current: null,  // {id, page}
  tabsKey: '',

  start() {
    // ESPHome's index page has no viewport tag, so phones would lay the page out 980 px wide and shrink it.
    if (!document.querySelector('meta[name="viewport"]')) {
      document.head.appendChild(h('meta', { name: 'viewport', content: 'width=device-width, initial-scale=1, viewport-fit=cover' }));
    }
    document.documentElement.lang = navigator.language || 'en';
    const root = document.querySelector('esp-app') || document.body;
    this.titleEl = h('span', { class: 'brand-name' }, 'Precision Feeder');
    this.clockEl = h('span', { class: 'header-clock' });
    this.connEl = h('span', { class: 'pill' });
    this.tabsEl = h('nav', { class: 'tabs', 'aria-label': 'Pages' });
    this.bannerEl = h('div', { class: 'banner-slot' });
    this.pageEl = h('main', { class: 'page', id: 'page', tabindex: '-1' });
    append(root,
      h('header', { class: 'header' },
        h('div', { class: 'header-inner' },
          h('span', { class: 'brand' }, icon('fish', 24), this.titleEl), h('span', { class: 'spacer' }),
          this.clockEl, this.connEl)),
      this.tabsEl,
      h('div', { class: 'container' }, this.bannerEl, this.pageEl),
      h('div', { id: 'toasts', class: 'toasts', 'aria-live': 'polite' }));
    banners.mount(this.bannerEl);
    window.addEventListener('hashchange', () => {
      this.navigated = true;  // the user chose a page: move focus to it once it is shown
      this.route();
    });
    store.subscribe(changed => this.update(changed));
    store.start();
    auth.refresh();
    // A feeder that is not set up yet (2.0.0 N6) opens the setup wizard, unless a page was asked for.
    auth.loadNetwork().then(n => {
      const want = location.hash.replace(/^#/, '');
      if (n && n.setup && (!want || (want === 'dashboard' && !this.navigated))) location.hash = '#setup';
    });
    this.update(new Set(['*all']));
    // Re-check the route once the first burst of entities has settled.
    const settle = setInterval(() => {
      if (this.settled()) {
        clearInterval(settle);
        this.update(new Set(['*settled']));
      }
    }, 200);
  },

  settled() {
    return store.status === 'online' && store.entities.size > 0 && Date.now() - store.lastNewEntity > SETTLE_MS;
  },

  visibleTabs() {
    return TABS.filter(t => PAGES[t.id] && t.shown());
  },

  update(changed) {
    if (changed.has('*restart')) appUpdate.check();
    this.updateHeader();
    this.updateTabs();
    banners.update();
    this.route();
    if (this.current && this.current.page.update) this.current.page.update(changed);
  },

  updateHeader() {
    const title = store.title || 'Precision Feeder';
    setText(this.titleEl, title);
    const pageTitle = this.current ? `${(TABS.find(t => t.id === this.current.id) || {}).title} · ${title}` : title;
    if (document.title !== pageTitle) document.title = pageTitle;
    const t = parseDeviceTime(store.text(E.deviceTime)) || parseLocalDateTime(store.text(E.deviceTime));
    setText(this.clockEl, t ? formatClock(t.hour, t.minute) : '');
    const online = store.status === 'online', paused = store.status === 'paused';
    setText(this.connEl, online ? 'Online' : paused ? 'Paused' : store.everOnline ? 'Offline' : 'Connecting');
    this.connEl.className = `pill ${online ? 'pill-ok' : store.everOnline && !paused ? 'pill-danger' : 'pill-muted'}`;
  },

  updateTabs() {
    const tabs = this.visibleTabs().filter(t => !t.hidden);
    const active = this.current ? this.current.id : '';
    const key = tabs.map(t => t.id).join() + '|' + active;
    if (key === this.tabsKey) return;
    this.tabsKey = key;
    clear(this.tabsEl);
    for (const t of tabs) {
      this.tabsEl.appendChild(h('a', { href: `#${t.id}`, class: t.id === active ? 'tab tab-active' : 'tab',
                                      'aria-current': t.id === active ? 'page' : null },
        icon(t.icon, 20), h('span', { class: 'tab-long' }, t.title), h('span', { class: 'tab-short' }, t.short)));
    }
  },

  /** Show the page the address asks for, or the first one there is once the build is known. */
  route() {
    // Pages build themselves from the entities the device reports, so nothing is shown until the first burst of
    // them has settled (a page mounted earlier would miss the parts of the build that had not arrived yet).
    if (!this.current && !this.settled()) {
      this.showLoading();
      return;
    }
    const [want, ...rest] = location.hash.replace(/^#/, '').split('/');
    const tabs = this.visibleTabs();
    let tab = tabs.find(t => t.id === want);
    if (!tab) {
      if (!this.settled()) {  // its entities may still be on their way
        if (!this.current) this.showLoading();
        return;
      }
      tab = tabs.find(t => !t.hidden);
      if (want) history.replaceState(null, '', `#${tab.id}`);
    }
    const sub = rest.join('/');
    if (this.current && this.current.id === tab.id && this.current.sub === sub) return;
    if (this.current && this.current.page.unmount) this.current.page.unmount();
    clear(this.pageEl);
    this.current = { id: tab.id, sub, page: PAGES[tab.id] };
    // Every page starts with its name as a heading, for screen readers (the tab bar shows it to everyone else).
    this.pageEl.appendChild(h('h1', { class: 'sr-only' }, tab.title));
    this.current.page.mount(this.pageEl, sub);
    this.updateTabs();
    document.title = `${tab.title} · ${store.title || 'Precision Feeder'}`;
    if (this.navigated) {
      this.navigated = false;
      this.pageEl.focus({ preventScroll: true });
      window.scrollTo(0, 0);
    }
  },

  showLoading() {
    if (this.pageEl.querySelector('.loading')) return;
    clear(this.pageEl);
    this.pageEl.appendChild(h('div', { class: 'loading' }, h('span', { class: 'spinner', 'aria-hidden': 'true' }),
      h('span', {}, 'Connecting to the feeder…')));
  },
};

app.start();
